function syncViewportHeight(){document.documentElement.style.setProperty('--app-height',`${window.innerHeight}px`)}
async function enterFullscreen(){
  try{
    const el=document.documentElement;
    if(!document.fullscreenElement){await (el.requestFullscreen?.({navigationUI:'hide'})||el.webkitRequestFullscreen?.())}
    try{await screen.orientation?.lock?.('landscape')}catch(_e){}
    syncViewportHeight();
    return true;
  }catch(_e){syncViewportHeight();return false}
}
function armFullscreen(){
  const handler=()=>{enterFullscreen();document.removeEventListener('pointerdown',handler,true);document.removeEventListener('touchend',handler,true)};
  document.addEventListener('pointerdown',handler,true,{once:true});
  document.addEventListener('touchend',handler,true,{once:true});
}

