function normalizeDifficulty(id){return DIFFICULTY_DEFS[id]?id:'normal'}
function currentDifficulty(){return DIFFICULTY_DEFS[normalizeDifficulty(state.difficulty)]}
function persistDifficulty(id){state.difficulty=normalizeDifficulty(id);localStorage.setItem('valeEmpires.difficulty',state.difficulty);state.difficultyChangedAt=Date.now();return state.difficulty}
function selectDifficulty(id){persistDifficulty(id);updateDifficultyUI();window.VALE_AUDIO?.playSfx?.('ui-click',{category:'ui',volume:.45,minGap:100})}
function updateDifficultyUI(){const d=currentDifficulty();document.querySelectorAll('.difficulty-option').forEach(b=>b.classList.toggle('selected',b.dataset.difficulty===d.id));if($('selectedDifficultyName'))$('selectedDifficultyName').textContent=d.label;if($('selectedDifficultyDescription'))$('selectedDifficultyDescription').textContent=d.description;if($('aiDifficulty'))$('aiDifficulty').textContent=d.label}
function applyDifficultyPlayerModifiers(){const d=currentDifficulty();for(const k of Object.keys(state.stock))state.stock[k]=Math.max(0,Math.round(state.stock[k]*d.playerResources));for(const u of state.units){if(u.type==='villager')continue;u.attack=Math.max(1,Math.round(u.attack*d.playerCombat));u.maxHp=Math.max(1,Math.round(u.maxHp*d.playerCombat));u.hp=u.maxHp}}
function difficultyReward(reward){const mult=currentDifficulty().reward;return Object.fromEntries(Object.entries(reward||{}).map(([k,v])=>[k,Math.max(1,Math.round(v*mult))]))}
function difficultyRank(id){return ['story','easy','normal','hard','conqueror'].indexOf(normalizeDifficulty(id))}

