function missionByKey(key){return CAMPAIGN_MISSIONS.find(m=>m.key===key)||CAMPAIGN_MISSIONS[0]}
function defaultCampaignProgress(){return{unlocked:['foundation'],completed:[],cumulativeRewards:{wood:0,food:0,gold:0,stone:0},best:{},updatedAt:new Date().toISOString()}}
function normalizeCampaignProgress(p){const d=defaultCampaignProgress();if(!p||typeof p!=='object')return d;const valid=CAMPAIGN_MISSIONS.map(m=>m.key),completed=Array.isArray(p.completed)?p.completed.filter(k=>valid.includes(k)):[],unlocked=Array.isArray(p.unlocked)?p.unlocked.filter(k=>valid.includes(k)):['foundation'];if(!unlocked.includes('foundation'))unlocked.unshift('foundation');return{unlocked:[...new Set(unlocked)],completed:[...new Set(completed)],cumulativeRewards:{...d.cumulativeRewards,...(p.cumulativeRewards||{})},best:p.best&&typeof p.best==='object'?p.best:{},updatedAt:p.updatedAt||d.updatedAt}}
function loadCampaignProgress(){try{return normalizeCampaignProgress(JSON.parse(localStorage.getItem('valeEmpires.campaign')||'null'))}catch{return defaultCampaignProgress()}}
function persistCampaignProgress(){state.campaignProgress=normalizeCampaignProgress(state.campaignProgress);state.campaignProgress.updatedAt=new Date().toISOString();localStorage.setItem('valeEmpires.campaign',JSON.stringify(state.campaignProgress));return state.campaignProgress}
function normalizeCampaignState(c){const key=missionByKey(c?.currentMission||state.campaignSelected).key;return{currentMission:key,startedAt:Number(c?.startedAt)||Date.now(),result:c?.result||null,midpointShown:!!c?.midpointShown,introShown:!!c?.introShown,elapsed:Number(c?.elapsed)||0,lastHudUpdate:0,difficulty:normalizeDifficulty(c?.difficulty||state.difficulty)}}
function campaignMilitaryCount(){return state.units.filter(u=>u.type&&u.type!=='villager'&&u.hp>0).length}
function campaignBuildingCount(type){return state.buildings.filter(b=>b.complete&&b.type===type).length}
