function objectiveDone(o){return Number(o.current)>=Number(o.target)}
function rewardText(reward){return Object.entries(reward||{}).map(([k,v])=>`${v} ${labelResource(k)}`).join(' • ')}

function currentNation(){const id=state.profile?.nation||'england';return NATION_DEFS[id]||NATION_DEFS.england}
function nationById(id){return NATION_DEFS[id]||NATION_DEFS.england}
function nationMod(group,key=null,nation=currentNation()){const g=nation?.modifiers?.[group];if(key===null)return Number(g)||0;if(typeof g==='object')return Number(g[key]||g.all)||0;return 0}
function civTechEffects(nation=currentNation(),done=state.civTechDone){return done===nation.uniqueTech.key?(nation.uniqueTech.effect||{}):{}}
function civEffect(name,type=null,nation=currentNation(),done=state.civTechDone){const e=civTechEffects(nation,done);let v=Number(e[name])||0;if(type)v+=Number(e[type+name.charAt(0).toUpperCase()+name.slice(1)])||0;return v}
function adjustedTechCost(cost,nation=currentNation()){const reduction=Math.max(0,Math.min(.35,nationMod('techCost',null,nation)));return Object.fromEntries(Object.entries(cost||{}).map(([k,v])=>[k,Math.max(1,Math.round(v*(1-reduction)))]))}
function adjustedTechTime(time,nation=currentNation(),done=state.civTechDone){const base=nationMod('techTime',null,nation)+civEffect('techTime',null,nation,done);return Math.max(3000,Math.round(time*(1-Math.min(.45,base))))}
function rivalNationFor(player){const order=['england','france','byzantium','mongol','cordoba','norse'];const i=Math.max(0,order.indexOf(player));return order[(i+1)%order.length]}

