const TECH_CATEGORIES={economy:{label:'ECONOMIA',icon:'assets/ui/icons-upgrade/resources/icon-gold.png'},military:{label:'MILITAR',icon:'assets/ui/icons-upgrade/military/icon-infantry.png'},defense:{label:'DEFESA',icon:'assets/ui/icons-upgrade/commands/icon-defend.png'}};
function techByKey(key){return TECH_DEFS.find(t=>t.key===key)||null}
function hasTech(key){return state.technologies.includes(key)}
function techEffectTotal(name,type=null){let total=0;for(const key of state.technologies){const t=techByKey(key),e=t?.effect||{};total+=Number(e[name])||0;if(type==='archer')total+=Number(e.archerAttack&&name==='attackAll'?e.archerAttack:0)||0;if(type==='cavalry'&&name==='hpAll')total+=Number(e.cavalryHp)||0}return total}
function effectiveGatherMultiplier(resource){let bonus=techEffectTotal('gatherAll')+nationMod('gather',resource)+civEffect('gatherAll');if(resource==='food')bonus+=techEffectTotal('gatherFood')+civEffect('gatherFood');if(resource==='gold'||resource==='stone')bonus+=techEffectTotal('gatherMinerals')+civEffect('gatherMinerals');return currentEra().gatherMultiplier*(1+bonus)}
function effectiveConstructionMultiplier(){return currentEra().constructionMultiplier*(1+techEffectTotal('construction')+nationMod('construction')+civEffect('construction'))}
function effectiveProductionMultiplier(){return currentEra().productionMultiplier*(1+techEffectTotal('production')+nationMod('production')+civEffect('production'))}
function effectiveCombatMultiplier(type){let bonus=techEffectTotal('attackAll')+nationMod('attack','all')+nationMod('attack',type)+civEffect('attackAll')+civEffect('attack',type);if(type==='archer')bonus+=TECH_DEFS.filter(t=>hasTech(t.key)).reduce((s,t)=>s+(Number(t.effect?.archerAttack)||0),0)+civEffect('archerAttack');if(type==='cavalry')bonus+=civEffect('cavalryAttack');if(type==='infantry')bonus+=civEffect('infantryAttack');return currentEra().combatMultiplier*(1+bonus)}
function effectiveHpMultiplier(type){let bonus=techEffectTotal('hpAll')+nationMod('hp','all')+nationMod('hp',type)+civEffect('hpAll')+civEffect('hp',type);if(type==='cavalry')bonus+=TECH_DEFS.filter(t=>hasTech(t.key)).reduce((s,t)=>s+(Number(t.effect?.cavalryHp)||0),0)+civEffect('cavalryHp');if(type==='infantry')bonus+=civEffect('infantryHp');return 1+bonus}
function effectiveSpeedMultiplier(type){let bonus=nationMod('speed','all')+nationMod('speed',type)+civEffect('speedAll')+civEffect('speed',type);if(type==='cavalry')bonus+=TECH_DEFS.filter(t=>hasTech(t.key)).reduce((s,t)=>s+(Number(t.effect?.cavalrySpeed)||0),0)+civEffect('cavalrySpeed');if(type==='archer')bonus+=civEffect('archerSpeed');if(type==='infantry')bonus+=civEffect('infantrySpeed');return 1+bonus}
function effectiveArmorBonus(type=null){return Math.floor(techEffectTotal('armorAll')+nationMod('armor','all')+(type?nationMod('armor',type):0)+civEffect('armorAll')+(type?civEffect('armor',type):0))}
function effectiveBuildingHpMultiplier(){return currentEra().buildingHpMultiplier*(1+techEffectTotal('buildingHp')+nationMod('buildingHp')+civEffect('buildingHp'))}
function effectiveStorageBonus(){return Math.round(TECH_DEFS.filter(t=>hasTech(t.key)).reduce((s,t)=>s+(Number(t.effect?.storage)||0),0)+nationMod('storage')+civEffect('storage'))}
function effectivePopulationBonus(){return Math.round(TECH_DEFS.filter(t=>hasTech(t.key)).reduce((s,t)=>s+(Number(t.effect?.population)||0),0)+nationMod('population')+civEffect('population'))}
function currentEra(){return ERA_DEFS[Math.max(0,Math.min(ERA_DEFS.length-1,state.eraIndex||0))]}
function eraFor(index){return ERA_DEFS[Math.max(0,Math.min(ERA_DEFS.length-1,index||0))]}
function eraIndexLabel(index){return eraFor(index).label}



