function show(name){const target=screens[name]?name:(screens.menu?'menu':'loading');if(state.active==='game'&&target!=='game')performAutosave('screen-change');window.VALE_AUDIO?.setScene?.(target);const transition=$('screenTransition');if(transition){transition.classList.add('playing');setTimeout(()=>transition.classList.remove('playing'),220)}Object.entries(screens).forEach(([k,e])=>{if(!e)return;e.classList.toggle('active',k===target);if(k===target){e.classList.remove('screen-enter');void e.offsetWidth;e.classList.add('screen-enter')}});if(name!==target)console.warn('Tela solicitada ausente, redirecionando em segurança:',name,'->',target);state.active=target}
function status(t){if($('hudStatus'))$('hudStatus').textContent=t;showStatusToast(t);if(/insuficiente|bloquead|inválido|erro|falha/i.test(t))window.VALE_AUDIO?.playSfx?.('ui-error',{category:'ui',volume:.72,minGap:220});else if(/concluíd|captur|alcançada/i.test(t))window.VALE_AUDIO?.playSfx?.('notification',{category:'ui',volume:.62,minGap:220});if(/vitória|concluíd|captur|erro|falha|derrot/i.test(t))haptic(/erro|falha|derrot/i.test(t)?[35,40,35]:18)}
function showStatusToast(message){const stack=$('toastStack');if(!stack||!message)return;const toast=document.createElement('div');toast.className='status-toast'+(/insuficiente|bloquead|erro|derrot|falha|limite/i.test(message)?' warning':'');toast.dataset.toast=String(++state.toastSeq);toast.textContent=message;stack.appendChild(toast);while(stack.children.length>3)stack.firstElementChild.remove();setTimeout(()=>toast.remove(),3800)}
