window.addEventListener('error',e=>recover(e.error||new Error(e.message)));window.addEventListener('unhandledrejection',e=>recover(e.reason||'Promise rejeitada'));
async function preload(){let n=0;await Promise.all(critical.map(src=>new Promise(res=>{const im=new Image();im.onload=()=>done(im);im.onerror=()=>{state.errors.push(src);done(null)};im.src=src;function done(img){if(img)state.assets[src]=img;n++;const pc=Math.round(n/critical.length*100);$('progressBar').style.width=pc+'%';$('progressText').textContent=pc+'%';$('loadingHint').textContent=img?'Validado: '+src.split('/').pop():'Fallback ativado: '+src;res()}})));await new Promise(r=>setTimeout(r,300))}
function visualQualityLabel(q){return q==='premium'?'PREMIUM':q==='balanced'?'EQUILIBRADO':'DESEMPENHO'}
function setVisualQuality(q){if(!['premium','balanced','performance'].includes(q))q='balanced';state.visualQuality=q;localStorage.setItem('valeEmpires.visualQuality',q);document.body.dataset.visualQuality=q;const app=$('app');if(app)app.dataset.visualQuality=q;const badge=$('visualQualityBadge');if(badge)badge.textContent=visualQualityLabel(q);initializeAmbientParticles();status(`Qualidade visual: ${visualQualityLabel(q)}`)}
function updateVisualQualityDescription(){const el=$('visualQualityDescription');if(!el)return;el.textContent=state.visualQuality==='premium'?'Iluminação, partículas e feedback visual completos.':state.visualQuality==='balanced'?'Efeitos moderados para manter boa fluidez.':'Reduz efeitos para aparelhos mais simples.'}
function initializeAmbientParticles(){const count=state.safe||state.visualQuality==='performance'?0:state.visualQuality==='balanced'?18:42;state.ambientParticles=Array.from({length:count},(_,i)=>({x:Math.random()*innerWidth,y:Math.random()*innerHeight,vx:(Math.random()-.5)*.045,vy:-.025-Math.random()*.055,r:.7+Math.random()*1.8,a:.08+Math.random()*.24,phase:Math.random()*Math.PI*2,warm:i%3===0}))}
function updatePremiumVisuals(dt){state.visualClock=(state.visualClock+dt/240000)%1;if(state.cameraShake>0){state.cameraShake=Math.max(0,state.cameraShake-dt*.035);state.shakeX=(Math.random()-.5)*state.cameraShake;state.shakeY=(Math.random()-.5)*state.cameraShake}else{state.shakeX=0;state.shakeY=0}for(const p of state.ambientParticles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.phase+=dt*.001;if(p.y<-8){p.y=innerHeight+8;p.x=Math.random()*innerWidth}if(p.x<-8)p.x=innerWidth+8;if(p.x>innerWidth+8)p.x=-8}const overlay=$('worldLighting');if(overlay){const a=state.visualClock*Math.PI*2,sun=Math.max(0,Math.sin(a)),dusk=Math.max(0,Math.sin(a-Math.PI));let bg,op;if(state.visualQuality==='performance'||state.safe){op=0}else if(sun>.35){bg='linear-gradient(135deg,rgba(255,220,154,.09),rgba(19,45,82,.16))';op=.10}else if(dusk>.15){bg='linear-gradient(135deg,rgba(255,139,79,.18),rgba(28,32,75,.28))';op=.22}else{bg='linear-gradient(135deg,rgba(25,55,100,.22),rgba(2,9,26,.48))';op=.32}overlay.style.background=bg;overlay.style.opacity=String(op)}}
function drawScreenAtmosphere(){if(state.safe||state.visualQuality==='performance'||!state.ambientParticles.length)return;const c=state.ctx;c.save();c.globalCompositeOperation='screen';for(const p of state.ambientParticles){c.globalAlpha=p.a*(.7+.3*Math.sin(p.phase));c.fillStyle=p.warm?'#f7dca0':'#b6d6e5';c.beginPath();c.arc(p.x,p.y,p.r,0,Math.PI*2);c.fill()}c.restore()}
function triggerCameraShake(amount=8){if(state.safe||state.visualQuality==='performance')return;state.cameraShake=Math.max(state.cameraShake,amount)}
function createCommandFeedback(sx,sy){haptic(10);const game=$('gameScreen');if(!game)return;const marker=document.createElement('div');marker.className='command-marker-premium';marker.style.left=sx+'px';marker.style.top=sy+'px';game.appendChild(marker);setTimeout(()=>marker.remove(),850)}
function pulseResourceElement(key){const id='stock'+key.charAt(0).toUpperCase()+key.slice(1),el=$(id);if(!el)return;const chip=el.closest('.resource-chip');if(!chip)return;chip.classList.remove('resource-flash');void chip.offsetWidth;chip.classList.add('resource-flash');setTimeout(()=>chip.classList.remove('resource-flash'),500)}

function applyAccessibility(){
  document.body.classList.toggle('access-high-contrast',accessPrefs.highContrast);
  document.body.classList.toggle('access-reduced-motion',accessPrefs.reducedMotion);
  document.body.classList.toggle('access-large-ui',accessPrefs.largeUI);
  document.body.classList.toggle('access-color-safe',accessPrefs.colorSafe);
  document.documentElement.style.setProperty('--ui-scale',String(accessPrefs.uiScale));
}
function persistAccessibility(){
  localStorage.setItem('valeEmpires.access.highContrast',String(accessPrefs.highContrast));
  localStorage.setItem('valeEmpires.access.reducedMotion',String(accessPrefs.reducedMotion));
  localStorage.setItem('valeEmpires.access.largeUI',String(accessPrefs.largeUI));
  localStorage.setItem('valeEmpires.access.colorSafe',String(accessPrefs.colorSafe));
  localStorage.setItem('valeEmpires.access.uiScale',String(accessPrefs.uiScale));
  localStorage.setItem('valeEmpires.access.haptics',String(accessPrefs.haptics));
  applyAccessibility();
}
function haptic(pattern=18){if(accessPrefs.haptics&&navigator.vibrate)navigator.vibrate(pattern)}
function updateAutosaveStatus(text=null,mode='ready'){
  const el=$('autosaveStatus');if(!el)return;
  el.classList.toggle('saving',mode==='saving');
  const saved=localStorage.getItem('valeEmpires.lastSaveAt');
  const label=text||(saved?`SALVO ${new Date(saved).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}`:'AUTOSAVE PRONTO');
  el.innerHTML=`<b>●</b> ${label}`;
}
function updateConnectionStatus(){const el=$('connectionStatus');if(!el)return;const online=navigator.onLine;el.classList.toggle('offline',!online);el.innerHTML=`<b>●</b> ${online?'ONLINE':'OFFLINE'}`}
function performAutosave(reason='interval'){
  if(state.active!=='game'||!state.map||!state.profile)return false;
  try{updateAutosaveStatus('SALVANDO...','saving');save({quiet:true,reason});setTimeout(()=>updateAutosaveStatus(),250);return true}catch(err){updateAutosaveStatus('FALHA AO SALVAR','error');console.warn('Autosave falhou',err);return false}
}
