function modeSaveKey(mode=state.gameMode){return mode==='skirmish'?'valeEmpires.save.skirmish':'valeEmpires.save.campaign'}
function restoreBackupSave(){
  const backup=localStorage.getItem('valeEmpires.save.backup');if(!backup){status('Nenhum backup automático disponível');return false}
  try{const parsed=JSON.parse(backup);const current=localStorage.getItem('valeEmpires.save');if(current)localStorage.setItem('valeEmpires.save.beforeRestore',current);localStorage.setItem('valeEmpires.save',backup);localStorage.setItem(modeSaveKey(parsed.gameMode),backup);updateContinue();status('Backup restaurado. Use Continuar para carregar.');haptic([20,30,20]);return true}catch(err){status('Backup inválido e não restaurado');return false}
}
function exportSave(){
  const raw=localStorage.getItem('valeEmpires.save');if(!raw){status('Não existe partida para exportar');return}
  const pack={schema:'vale-empires-save',schemaVersion:27,buildId:BUILD.buildId,exportedAt:new Date().toISOString(),save:JSON.parse(raw),profile:loadProfile(),campaignProgress:loadCampaignProgress()};
  const blob=new Blob([JSON.stringify(pack,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`vale-empires-save-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200);status('Save exportado com sucesso')
}
async function importSaveFile(file){
  if(!file)return;try{const data=JSON.parse(await file.text());const incoming=data?.schema==='vale-empires-save'?data.save:data;if(!incoming||typeof incoming!=='object'||!incoming.profile||!incoming.camera)throw new Error('Estrutura inválida');const current=localStorage.getItem('valeEmpires.save');if(current)localStorage.setItem('valeEmpires.save.backup',current);localStorage.setItem('valeEmpires.save',JSON.stringify(incoming));localStorage.setItem(modeSaveKey(incoming.gameMode),JSON.stringify(incoming));localStorage.setItem('valeEmpires.lastMode',incoming.gameMode==='skirmish'?'skirmish':'campaign');if(data.profile)localStorage.setItem('valeEmpires.profile',JSON.stringify(data.profile));if(data.campaignProgress)localStorage.setItem('valeEmpires.campaignProgress',JSON.stringify(data.campaignProgress));updateContinue();status('Save importado. Use Continuar para carregar.');haptic([30,35,30])}catch(err){status('Arquivo de save inválido')}
}
