function skirmishMilitaryCount(){return state.units.filter(u=>u.type&&u.type!=='villager'&&u.hp>0).length}
function skirmishProgress(){const config=state.skirmish||loadSkirmishConfig();if(config.victory==='conquest')return{label:'Abates e força rival',current:Math.min(20,state.kills),target:20,detail:`${state.kills}/20 abates • ${state.enemies.length} inimigos ativos`,complete:state.kills>=20&&state.enemies.length===0};if(config.victory==='domination'){const controlled=state.territoryStats.pointsPlayer||0,seconds=Math.floor((state.skirmishRuntime?.dominationMs||0)/1000);return{label:'Dominação territorial',current:Math.min(120,seconds),target:120,detail:`${controlled}/5 pontos • ${seconds}/120 s`,complete:controlled>=4&&seconds>=120}}const economy=Math.floor(Object.values(state.stock).reduce((a,b)=>a+(Number(b)||0),0));const army=skirmishMilitaryCount(),complete=state.eraIndex>=3&&army>=18&&economy>=2500;return{label:'Supremacia imperial',current:Number(complete),target:1,detail:`Era ${currentEra().label} • ${army}/18 tropas • ${economy}/2500 recursos`,complete}}
function updateSkirmishHUD(force=false){if(state.gameMode!=='skirmish'||!state.skirmish)return;const config=state.skirmish,progress=skirmishProgress();if($('missionHudChapter'))$('missionHudChapter').textContent='PARTIDA LIVRE';if($('missionHudTitle'))$('missionHudTitle').textContent=SKIRMISH_VICTORY_DEFS[config.victory].label;if($('missionHudProgress'))$('missionHudProgress').textContent=progress.detail;if($('missionTrackerTitle'))$('missionTrackerTitle').textContent=`Escaramuça • ${SKIRMISH_MAP_DEFS[config.mapSize].label}`;if($('missionTrackerText'))$('missionTrackerText').textContent=progress.detail;if($('btnMissionPanel'))$('btnMissionPanel').classList.toggle('complete',progress.complete)}
function updateSkirmish(dt){if(state.gameMode!=='skirmish'||!state.skirmishRuntime||state.skirmishRuntime.result)return;state.skirmishRuntime.elapsed+=dt;const controlled=state.territoryStats.pointsPlayer||0;if(state.skirmish.victory==='domination')state.skirmishRuntime.dominationMs=controlled>=4?state.skirmishRuntime.dominationMs+dt:0;updateSkirmishHUD();const alive=state.units.filter(u=>u.hp>0).length;if(alive===0){finishSkirmish(false,'Seu reino perdeu todas as unidades.');return}if(skirmishProgress().complete)finishSkirmish(true,'A condição de vitória foi alcançada.')}
function finishSkirmish(victory,message){if(!state.skirmishRuntime||state.skirmishRuntime.result)return;state.skirmishRuntime.result=victory?'victory':'defeat';window.VALE_AUDIO?.playResult?.(victory);const overlay=$('skirmishResultOverlay');if(!overlay)return;overlay.classList.remove('hidden');overlay.setAttribute('aria-hidden','false');$('skirmishResultIcon').src=victory?'assets/ui/icons-upgrade/status/icon-available.png':'assets/ui/icons-upgrade/status/icon-blocked.png';$('skirmishResultKicker').textContent=victory?'PARTIDA CONCLUÍDA':'PARTIDA ENCERRADA';$('skirmishResultTitle').textContent=victory?'Vitória na partida livre':'Derrota';$('skirmishResultText').textContent=message;const elapsed=Math.max(0,Math.floor(state.skirmishRuntime.elapsed/1000)),minutes=Math.floor(elapsed/60),seconds=String(elapsed%60).padStart(2,'0');$('skirmishResultStats').innerHTML=`Tempo: ${minutes}:${seconds}<br>Abates: ${state.kills} • Baixas: ${state.defeats}<br>Condição: ${SKIRMISH_VICTORY_DEFS[state.skirmish.victory].label}`;save({quiet:true})}
