  const map={accessHighContrast:'highContrast',accessReducedMotion:'reducedMotion',accessLargeUI:'largeUI',accessColorSafe:'colorSafe',accessHaptics:'haptics'};Object.entries(map).forEach(([id,key])=>{const el=$(id);if(!el)return;el.checked=accessPrefs[key];el.onchange=()=>{accessPrefs[key]=el.checked;persistAccessibility();haptic(12)}});
  const scale=$('accessUIScale'),scaleLabel=$('accessScaleLabel');if(scale){scale.value=String(Math.round(accessPrefs.uiScale*100));scale.oninput=()=>{accessPrefs.uiScale=Number(scale.value)/100;if(scaleLabel)scaleLabel.textContent=scale.value+'%';persistAccessibility()}}if(scaleLabel)scaleLabel.textContent=Math.round(accessPrefs.uiScale*100)+'%';
  const health=$('saveHealth');if(health)health.textContent=saveHealthText();const saveNow=$('saveNowBtn');if(saveNow)saveNow.onclick=()=>{performAutosave('manual-settings');if(health)health.textContent=saveHealthText()};const restore=$('restoreBackupBtn');if(restore)restore.onclick=()=>{restoreBackupSave();if(health)health.textContent=saveHealthText()};const exp=$('exportSaveBtn');if(exp)exp.onclick=exportSave;const imp=$('importSaveBtn');if(imp)imp.onclick=()=>$('importSaveInput')?.click();const diag=$('diagnosticsSettingsBtn');if(diag)diag.onclick=()=>window.VALE_RELEASE_GUARD?.downloadReport?.();
