function openCredits(){openModal('Créditos',`<div class="credit-card"><p><strong>Vale Empires</strong></p><p>Fase 42 — infraestrutura imperial, logística profunda, obras públicas e corredores regionais avançados.</p><p>Campanha medieval, partida livre, diplomacia, entrepostos estrangeiros, caravanas físicas, portos, navios mercantes, estaleiros, frotas militares, transportes anfíbios, fortes costeiros, muralhas urbanas, portões, torres de cerco, aríetes, conquista de portos e cidades, administração urbana, governadores, províncias, leis regionais, tributação, rede de cidades, moral cultural, guerra de informações, espionagem, religião/civilização abstrata, tradições profundas, facções sociais, identidade nacional, estabilidade popular avançada, economia interna, abastecimento, impostos, setores produtivos, classes econômicas, infraestrutura imperial, logística profunda, obras públicas, corredores regionais, demografia, comércio exterior, tratados econômicos, rotas internacionais, embargos, tarifas, seis civilizações, três idiomas, PWA, acessibilidade e arquitetura multiera.</p><p>${BUILD.buildId} • ${BUILD.compiledAt}</p><div class="legal-links"><a href="legal/privacy.html" target="_blank" rel="noopener">Privacidade</a><a href="legal/terms.html" target="_blank" rel="noopener">Termos</a><a href="legal/licenses.html" target="_blank" rel="noopener">Licenças</a></div><p class="legal-note">Documentos comerciais em formato de preparação. Recomenda-se revisão jurídica antes da venda pública.</p></div>`)}

function loadSave(mode=null){try{const raw=mode?localStorage.getItem(modeSaveKey(mode)):localStorage.getItem('valeEmpires.save');const parsed=JSON.parse(raw||'null');return window.VALE_RELEASE_GUARD?.migrateSave?window.VALE_RELEASE_GUARD.migrateSave(parsed):parsed}catch(err){window.VALE_RELEASE_GUARD?.addEvent?.('save-error','Falha ao ler save',{message:err.message,mode});return null}}
function loadProfile(){try{return JSON.parse(localStorage.getItem('valeEmpires.profile')||'null')}catch{return null}}
function openPeriodSelection(){state.pendingPeriod=normalizeEraPack(localStorage.getItem('valeEmpires.eraPack')||state.periodPack||'medieval');renderPeriodSelection();show('period')}
function selectPeriodPack(id){const pack=eraPackById(id);state.pendingPeriod=pack.id;renderPeriodSelection();if(!pack.enabled){status(`${pack.label} está preparada na arquitetura, mas ainda não está liberada para partidas.`);window.VALE_AUDIO?.playSfx?.('ui-error',{category:'ui',volume:.48,minGap:200})}else window.VALE_AUDIO?.playSfx?.('ui-click',{category:'ui',volume:.42,minGap:120})}
