function nearestPassable(wx,wy){if(isPassable(wx,wy))return{x:wx,y:wy};const ts=state.map.tile,cx=Math.floor(wx/ts),cy=Math.floor(wy/ts);for(let r=1;r<7;r++)for(let oy=-r;oy<=r;oy++)for(let ox=-r;ox<=r;ox++){if(Math.abs(ox)!==r&&Math.abs(oy)!==r)continue;const x=cx+ox,y=cy+oy;if(state.map.passable[y]?.[x])return{x:x*ts+ts/2,y:y*ts+ts/2}}return null}
