function cellKey(x,y){return y*state.map.cols+x}
function buildingBlocksCell(cx,cy,ignoreEntity=null){const p=cellToWorld(cx,cy);if(Math.hypot(p.x-state.townCenter.x,p.y-state.townCenter.y)<state.townCenter.r*.78)return true;for(const b of state.buildings){if(ignoreEntity&&ignoreEntity.buildingId===b.id)continue;if(b.type==='cityGate'&&b.complete&&b.gateOpen)continue;const d=BUILDING_DEFS[b.type],radius=(d?.size||58)*.66;if(Math.hypot(p.x-b.x,p.y-b.y)<radius)return true}for(const b of (state.enemyAI?.buildings||[])){const d=BUILDING_DEFS[b.type]||{size:b.type==='townCenter'?92:62},radius=(d.size||62)*.62;if(Math.hypot(p.x-b.x,p.y-b.y)<radius)return true}for(const d of (state.coastalSiege?.enemyDefenses||[])){if(d.hp>0&&Math.hypot(p.x-d.x,p.y-d.y)<(d.type==='tower'?42:48))return true}for(const d of (state.urbanSiege?.enemyStructures||[])){if(d.hp<=0)continue;if(d.type==='gate'&&d.open)continue;if(Math.hypot(p.x-d.x,p.y-d.y)<(d.type==='tower'?46:d.type==='keep'?70:50))return true}return false}
function cellWalkable(cx,cy,startCell=null,endCell=null,ignoreEntity=null){if(cx<0||cy<0||cx>=state.map.cols||cy>=state.map.rows)return false;if(startCell&&cx===startCell.x&&cy===startCell.y)return true;if(endCell&&cx===endCell.x&&cy===endCell.y)return !!state.map.passable[cy]?.[cx];return !!state.map.passable[cy]?.[cx]&&!buildingBlocksCell(cx,cy,ignoreEntity)}
