function updateSelection(){$('selectionCount').textContent=state.selected.size;const sel=state.units.filter(u=>state.selected.has(u.id));const army=sel.filter(u=>u.type&&u.type!=='villager').length;const villagers=sel.filter(u=>!u.type||u.type==='villager').length;$('selectionHelp').textContent=state.selected.size?(army?`${army} tropa(s) • comando atual: ${state.activeTactic}`:'Aldeões prontos para coletar ou construir.'):'Selecione unidades ou arraste uma caixa.';if($('selectionTitle'))$('selectionTitle').textContent=army?'Exército selecionado':villagers?'Aldeões selecionados':'Nada selecionado';if($('selectionIcon'))$('selectionIcon').src=army?'assets/ui/icons-upgrade/military/icon-select-all-army.png':villagers?'assets/ui/icons-upgrade/villagers/icon-select-villager.png':'assets/ui/icons-upgrade/minimap/icon-marker.png';state.buildMenuOpen=false;state.militaryMenuOpen=false;state.navalMenuOpen=false;updateContextHUD()}
function resourceAt(wx,wy){return state.map.resources.filter(r=>r.amount>0).sort((a,b)=>Math.hypot(a.x-wx,a.y-wy)-Math.hypot(b.x-wx,b.y-wy))[0]}
function command(sx,sy){createCommandFeedback(sx,sy);window.VALE_AUDIO?.playSfx?.('command-move',{volume:.72,minGap:110});if(!state.selected.size){status('Selecione ao menos uma unidade');return}const w=screenToWorld(sx,sy);const enemy=enemyAt(sx,sy);if(enemy){assignAttackTarget(enemy);return}const near=resourceAt(w.x,w.y);if(near&&Math.hypot(near.x-w.x,near.y-w.y)<78){assignResourceToSelected(near);return}const base=nearestPassable(w.x,w.y);if(!base){status('Destino bloqueado');return}const sel=state.units.filter(u=>state.selected.has(u.id));let routed=0;sel.forEach((u,i)=>{let ox=0,oy=0;if(state.activeTactic==='wedge'){const row=Math.floor(Math.sqrt(i)),side=i%2===0?-1:1;ox=side*row*42;oy=row*46}else{const c=Math.ceil(Math.sqrt(sel.length));ox=(i%c)*58-(c-1)*29;oy=Math.floor(i/c)*58}const candidate=nearestPassable(base.x+ox,base.y+oy);u.task=null;u.state='moving';if(candidate&&setDestination(u,candidate,true))routed++});updatePathStatsUI();status(`${routed}/${sel.length} unidade(s) receberam rota em formação ${state.activeTactic}`)}
function assignGather(type){if(!state.selected.size){status('Selecione aldeões antes de ordenar a coleta');return}const sel=state.units.filter(u=>state.selected.has(u.id)&&(u.type==='villager'||!u.type));let assigned=0;sel.forEach(u=>{const r=state.map.resources.filter(r=>r.type===type&&r.amount>0).sort((a,b)=>Math.hypot(a.x-u.x,a.y-u.y)-Math.hypot(b.x-u.x,b.y-u.y))[0];if(r){u.task={kind:'gather',resourceId:r.id,resourceType:type};u.state='toResource';if(setDestination(u,nearestPassable(r.x,r.y),true))assigned++}});status(`${assigned} aldeão(ões) enviados para ${labelResource(type)}`);if(assigned)window.VALE_AUDIO?.playSfx?.('gather-'+type,{volume:.72,minGap:160})}
function assignResourceToSelected(resource){const sel=state.units.filter(u=>state.selected.has(u.id)&&(u.type==='villager'||!u.type));sel.forEach(u=>{u.task={kind:'gather',resourceId:resource.id,resourceType:resource.type};u.state='toResource';setDestination(u,nearestPassable(resource.x,resource.y),true)});status(`${sel.length} aldeão(ões) enviados para ${labelResource(resource.type)}`);if(sel.length)window.VALE_AUDIO?.playSfx?.('gather-'+resource.type,{volume:.72,minGap:160})}
function labelResource(t){return {wood:'madeira',food:'alimento',gold:'ouro',stone:'pedra'}[t]||t}
function embarkedTroopCount(){return[...state.navalFleet,...(state.navalMilitary?.enemyFleet||[])].reduce((sum,s)=>sum+(s.faction==='player'&&Array.isArray(s.passengers)?s.passengers.length:0),0)}
function currentPopulation(){return state.units.length+embarkedTroopCount()}
function updateStockUI(){recalculateEconomy();for(const k of ['wood','food','gold','stone']){const value=Math.floor(state.stock[k]||0),oldValue=state.lastStockVisual[k];const el=$('stock'+k.charAt(0).toUpperCase()+k.slice(1));if(el)el.textContent=value;if(oldValue!==undefined&&value!==oldValue)pulseResourceElement(k);state.lastStockVisual[k]=value;const cap=$('cap'+k.charAt(0).toUpperCase()+k.slice(1));if(cap)cap.textContent=Math.floor(state.storage[k]||0)}if($('populationNow'))$('populationNow').textContent=currentPopulation();if($('populationCap'))$('populationCap').textContent=state.population.cap;updateEconomyUI()}
function recalculateEconomy(){const completed=state.buildings.filter(b=>b.complete),era=currentEra();state.population.cap=10+era.populationBonus+effectivePopulationBonus()+diplomacyPopulationBonus()+provincePopulationBonus()+completed.filter(b=>b.type==='house').length*5;state.storage={wood:500+era.storageBonus+effectiveStorageBonus(),food:500+era.storageBonus+effectiveStorageBonus(),gold:500+era.storageBonus+effectiveStorageBonus(),stone:500+era.storageBonus+effectiveStorageBonus()};for(const b of completed){if(b.type==='storehouse'){for(const k of ['wood','food','gold','stone'])state.storage[k]+=300}if(b.type==='mill')state.storage.food+=250;if(b.type==='lumberCamp')state.storage.wood+=250}for(const k of ['wood','food','gold','stone'])state.stock[k]=Math.min(state.stock[k]||0,state.storage[k])}
function updateEconomyUI(){const villagers=state.units.filter(u=>u.type==='villager'||!u.type);const busy=villagers.filter(u=>u.state!=='idle').length;if($('workersBusy'))$('workersBusy').textContent=busy;if($('workersIdle'))$('workersIdle').textContent=villagers.length-busy;if($('buildingCount'))$('buildingCount').textContent=state.buildings.length;if($('totalGathered'))$('totalGathered').textContent=Math.floor(state.totalGathered);const first=state.productionQueue[0];if($('queueText'))$('queueText').textContent=first?`Aldeão • ${state.productionQueue.length} na fila`:'Fila vazia';if($('queueProgressBar'))$('queueProgressBar').style.width=first?Math.min(100,state.productionProgress/8000*100)+'%':'0%';updateMilitaryUI()}
function queueVillager(){recalculateEconomy();if(state.productionQueue.length>=5){status('Fila de produção cheia');return}if(currentPopulation()+state.productionQueue.length>=state.population.cap){status('Limite populacional atingido. Construa casas.');return}if((state.stock.food||0)<50){status('Alimento insuficiente para criar aldeão');return}state.stock.food-=50;state.productionQueue.push({type:'villager',time:Math.round(8000/effectiveProductionMultiplier()),era:state.eraIndex});updateStockUI();window.VALE_AUDIO?.playSfx?.('ui-confirm',{category:'ui',volume:.75,minGap:120});status('Aldeão adicionado à fila do Centro Urbano')}
function cancelLastQueue(){if(!state.productionQueue.length){status('A fila já está vazia');return}state.productionQueue.pop();state.stock.food=Math.min(state.storage.food,(state.stock.food||0)+50);if(!state.productionQueue.length)state.productionProgress=0;updateStockUI();status('Última produção cancelada e alimento devolvido')}
function spawnProducedVillager(){const id=Math.max(0,...state.units.map(u=>u.id))+1;for(let ring=2;ring<9;ring++)for(let a=0;a<Math.PI*2;a+=Math.PI/6){const x=state.townCenter.x+Math.cos(a)*ring*35,y=state.townCenter.y+Math.sin(a)*ring*35;if(isPassable(x,y)){const m=effectiveCombatMultiplier('villager'),hm=effectiveHpMultiplier('villager');state.units.push({id,name:'Aldeão '+id,x,y,r:22,target:null,speed:2.05+(id%3)*.12,type:'villager',hp:Math.round(70*m*hm),maxHp:Math.round(70*m*hm),attack:Math.max(3,Math.round(3*m)),range:22,armor:Math.floor(state.eraIndex/2)+effectiveArmorBonus('villager'),eraBorn:state.eraIndex,carry:{type:null,amount:0,cap:20},task:null,state:'idle',gatherTimer:0});updateStockUI();status('Novo aldeão criado no Centro Urbano');return}}}
function updateProduction(dt){if(!state.productionQueue.length){state.productionProgress=0;updateEconomyUI();return}recalculateEconomy();if(currentPopulation()>=state.population.cap){status('Produção pausada: limite populacional atingido');updateEconomyUI();return}state.productionProgress+=dt;if(state.productionProgress>=state.productionQueue[0].time){state.productionProgress=0;state.productionQueue.shift();spawnProducedVillager()}updateEconomyUI()}
function update(dt){state.animationClock+=dt;state.animationStats.frames++;state.animationStats.units=0;state.animationStats.enemyUnits=0;state.animationStats.buildings=0;updatePremiumVisuals(dt);updateEraResearch(dt);updateTechResearch(dt);updateCivilizationResearch(dt);updateConstruction(dt);updateProduction(dt);updateMilitaryProduction(dt);updateEnemyAI(dt);updateDiplomacy(dt);updateTradeWorld(dt);updateNavalWorld(dt);updateNavalMilitary(dt);updateAmphibious(dt);updateCoastalSiege(dt);updateUrbanSiege(dt);updateCityAdministration(dt);updateProvinceNetwork(dt);updateVisibility(dt);updateTerritory(dt);const speed=8/state.camera.zoom;if(state.keys.a||state.keys.arrowleft)state.camera.x-=speed;if(state.keys.d||state.keys.arrowright)state.camera.x+=speed;if(state.keys.w||state.keys.arrowup)state.camera.y-=speed;if(state.keys.s||state.keys.arrowdown)state.camera.y+=speed;clamp();state.units.forEach(u=>{
if(u.task?.kind==='gather'){const r=state.map.resources.find(x=>x.id===u.task.resourceId);if(!r||r.amount<=0){u.task=null;u.target=null;u.state='idle';return}
if(u.state==='toResource'){if(Math.hypot(u.x-r.x,u.y-r.y)<54){u.target=null;u.state='gathering'}else if(!u.target)setDestination(u,nearestPassable(r.x,r.y),true)}
else if(u.state==='gathering'){u.gatherTimer+=dt;if(u.gatherTimer>=520){u.gatherTimer=0;const take=Math.min(2*effectiveGatherMultiplier(r.type),r.amount,u.carry.cap-u.carry.amount);if(take>0){r.amount-=take;u.carry.type=r.type;u.carry.amount+=take}if(u.carry.amount>=u.carry.cap||r.amount<=0){u.state='returning';setDestination(u,{x:state.townCenter.x,y:state.townCenter.y},true)}}}
else if(u.state==='returning'){if(Math.hypot(u.x-state.townCenter.x,u.y-state.townCenter.y)<72){if(u.carry.amount>0){const room=Math.max(0,(state.storage[u.carry.type]||500)-(state.stock[u.carry.type]||0));const delivered=Math.min(room,u.carry.amount);state.stock[u.carry.type]=(state.stock[u.carry.type]||0)+delivered;state.totalGathered+=delivered;u.carry.amount=0;u.carry.type=null;updateStockUI()}if(r.amount>0){u.state='toResource';setDestination(u,nearestPassable(r.x,r.y),true)}else{u.task=null;u.target=null;u.state='idle'}}}
}
if(u.task?.kind==='patrol'&&!u.target){const atA=Math.hypot(u.x-u.task.a.x,u.y-u.task.a.y)<15;setDestination(u,atA?u.task.b:u.task.a,true);u.state='patrolling'}if(u.target)navigateEntity(u,dt,state.units)});updateCombat(dt);updatePathStatsUI();updateTutorial(dt);if(state.gameMode==='skirmish')updateSkirmish(dt);else updateCampaign(dt);}
