function drawSpriteEntity(img,x,y,w,h,opts={}){const c=state.ctx,sel=!!opts.selected;c.save();c.translate(x,y);const shadowW=opts.shadowW||w*.46,shadowH=opts.shadowH||h*.12;c.fillStyle='rgba(0,0,0,.34)';c.beginPath();c.ellipse(0,h*.28,shadowW,shadowH,0,0,Math.PI*2);c.fill();if(sel){c.strokeStyle='#f4d56b';c.lineWidth=4;c.beginPath();c.arc(0,0,Math.max(w,h)*.42+10,0,Math.PI*2);c.stroke()}if(img)c.drawImage(img,-w/2,-h/2,w,h);if(opts.progressBar){const p=opts.progressBar;c.fillStyle='rgba(64,26,22,.85)';c.fillRect(-w*.42,-h*.56,w*.84,8);c.fillStyle=p.color||'#4c9b4b';c.fillRect(-w*.42,-h*.56,w*.84*Math.max(0,Math.min(1,p.value)),8)}if(opts.badgeText){c.fillStyle='rgba(7,15,27,.72)';c.fillRect(-w*.28,h*.16,w*.56,16);c.fillStyle='#f5e5b5';c.font='bold 10px Georgia';c.textAlign='center';c.fillText(opts.badgeText,0,h*.28)}c.restore()}
function worldAnimationsEnabled(){return !state.safe&&!accessPrefs.reducedMotion&&state.visualQuality!=='performance'}
function unitAnimationPose(entity){const enabled=worldAnimationsEnabled(),now=performance.now(),id=Number(entity.id)||0,phase=now*.0105+id*1.73,stateName=String(entity.state||'idle'),moving=!!entity.target||['moving','engaging','toResource','returning','toBuild','toRepair','patrolling','retreating','engaged'].includes(stateName),working=['gathering','building','repairing'].includes(stateName),fighting=['fighting','attacking'].includes(stateName)||(stateName==='engaged'&&!entity.target),speed=entity.type==='cavalry'?1.35:1;let dx=entity.target?.x-entity.x||entity.pathGoal?.x-entity.x||1;const facing=dx<0?-1:1;if(!enabled)return{moving,working,fighting,bob:0,sway:0,lean:0,scale:1,lunge:0,facing,phase};return{moving,working,fighting,bob:moving?Math.abs(Math.sin(phase*speed))*4:Math.sin(phase*.45)*1.2,sway:moving?Math.sin(phase*speed)*.055:Math.sin(phase*.38)*.018,lean:moving?Math.sin(phase*speed)*.045:0,scale:1+(moving?Math.sin(phase*speed*2)*.022:Math.sin(phase*.4)*.012),lunge:fighting?Math.max(0,Math.sin(phase*1.8))*8:0,facing,phase}}
function drawUnitActivityOverlay(entity,pose,size,isEnemy=false){const c=state.ctx;c.save();c.translate(entity.x,entity.y);const side=pose.facing;const color=isEnemy?'#e06156':'#e7cf8a';if(pose.moving&&worldAnimationsEnabled()){for(let i=0;i<2;i++){const p=(pose.phase*.18+i*.5)%1;c.globalAlpha=(1-p)*.25;c.fillStyle='#c7aa78';c.beginPath();c.arc(-side*size*.12-p*12,(size*.28)+p*7,2+p*3,0,Math.PI*2);c.fill()}}if(pose.working){const a=Math.sin(pose.phase*1.8)*.8;c.strokeStyle=color;c.lineWidth=3;c.beginPath();c.moveTo(side*7,-2);c.lineTo(side*(18+Math.cos(a)*5),-15+Math.sin(a)*12);c.stroke();c.fillStyle='#b8bcc2';c.beginPath();c.arc(side*(20+Math.cos(a)*5),-17+Math.sin(a)*12,4,0,Math.PI*2);c.fill()}if(pose.fighting){const a=-.8+Math.max(0,Math.sin(pose.phase*1.8))*1.5;c.strokeStyle=color;c.lineWidth=3;c.beginPath();c.moveTo(side*8,-3);c.lineTo(side*(23+Math.cos(a)*8),-17+Math.sin(a)*11);c.stroke();if(entity.type==='archer'){c.strokeStyle='#d7b77b';c.lineWidth=2;c.beginPath();c.arc(side*18,-5,12,-1.2,1.2);c.stroke()}}c.restore()}
function drawAnimatedUnit(entity,img,size,isEnemy=false){const c=state.ctx,pose=unitAnimationPose(entity),selected=!isEnemy&&state.selected.has(entity.id),shadowY=size*.30,shadowW=(entity.type==='cavalry'?size*.38:size*.30)*(1-Math.min(1,pose.bob/30));c.save();c.translate(entity.x,entity.y);c.fillStyle='rgba(0,0,0,.34)';c.beginPath();c.ellipse(0,shadowY,shadowW,size*.095,0,0,Math.PI*2);c.fill();if(selected){c.strokeStyle='#f4d56b';c.lineWidth=4;c.beginPath();c.arc(0,0,size*.47+8,0,Math.PI*2);c.stroke()}c.translate(pose.facing*pose.lunge,-pose.bob);c.rotate(pose.sway+pose.lean*pose.facing);c.scale(pose.facing*pose.scale,pose.scale);if(img)c.drawImage(img,-size/2,-size/2,size,size);if(isEnemy){c.globalCompositeOperation='source-atop';c.fillStyle='rgba(160,22,25,.32)';c.fillRect(-size/2,-size/2,size,size);c.globalCompositeOperation='source-over'}c.restore();drawUnitActivityOverlay(entity,pose,size,isEnemy);c.save();c.translate(entity.x,entity.y);const hp=Math.max(0,Math.min(1,(entity.hp||0)/(entity.maxHp||1)));c.fillStyle='rgba(64,26,22,.88)';c.fillRect(-size*.42,-size*.57,size*.84,7);c.fillStyle=isEnemy?'#d64a44':hp>.5?'#4c9b4b':'#c36c36';c.fillRect(-size*.42,-size*.57,size*.84*hp,7);const badge=isEnemy?'INIMIGO':entity.type==='villager'?String(entity.id):(entity.badge||({infantry:'INF',archer:'ARQ',cavalry:'CAV'}[entity.type]||entity.type));c.fillStyle='rgba(7,15,27,.72)';c.fillRect(-size*.30,size*.18,size*.60,15);c.fillStyle='#f5e5b5';c.font='bold 9px Georgia';c.textAlign='center';c.fillText(badge,0,size*.29);if(entity.type==='villager'&&entity.carry?.amount>0){c.fillStyle='rgba(7,15,27,.72)';c.fillRect(-22,-size*.68,44,13);c.fillStyle=entity.carry.type==='wood'?'#6b3f20':entity.carry.type==='food'?'#78a541':entity.carry.type==='gold'?'#d6a52e':'#888';c.fillRect(-20,-size*.66,40*(entity.carry.amount/entity.carry.cap),9);c.strokeStyle='#f5e5b5';c.strokeRect(-20,-size*.66,40,9)}c.restore();if(isEnemy)state.animationStats.enemyUnits++;else state.animationStats.units++}
function drawBuildingAnimationDetails(b,d,w,h,isEnemy=false){if(!worldAnimationsEnabled())return;const c=state.ctx,now=performance.now(),phase=now*.002+(Number(b.id)||0),accent=isEnemy?'#d85549':'#e4bd62';c.save();c.translate(b.x,b.y);if(!b.complete){c.strokeStyle='rgba(229,195,119,.75)';c.lineWidth=2;for(let x=-w*.38;x<=w*.38;x+=w*.19){c.beginPath();c.moveTo(x,-h*.32);c.lineTo(x,h*.20);c.stroke()}c.beginPath();c.moveTo(-w*.45,-h*.05);c.lineTo(w*.45,-h*.05);c.stroke();for(let i=0;i<3;i++){const p=(phase*.8+i*.33)%1;c.globalAlpha=(1-p)*.8;c.fillStyle='#ffd36c';c.beginPath();c.arc((i-1)*w*.16,-h*.15-p*12,2+p*2,0,Math.PI*2);c.fill()}c.restore();return}if(['townCenter','barracks','archeryRange','stable','outpost'].includes(b.type)){const wave=Math.sin(phase*3)*5;c.strokeStyle='#7b5c2d';c.lineWidth=3;c.beginPath();c.moveTo(w*.28,-h*.38);c.lineTo(w*.28,-h*.76);c.stroke();c.fillStyle=accent;c.beginPath();c.moveTo(w*.29,-h*.75);c.quadraticCurveTo(w*.48+wave*.25,-h*.67,w*.58+wave*.2,-h*.58);c.lineTo(w*.29,-h*.58);c.closePath();c.fill()}if(b.type==='mill'){c.strokeStyle='#ead9ad';c.lineWidth=4;const a=phase*1.8;for(let i=0;i<4;i++){const r=a+i*Math.PI/2;c.beginPath();c.moveTo(0,-h*.15);c.lineTo(Math.cos(r)*w*.38,Math.sin(r)*h*.38-h*.15);c.stroke()}}if(['house','storehouse','lumberCamp','barracks'].includes(b.type)){for(let i=0;i<3;i++){const p=(phase*.45+i*.27)%1;c.globalAlpha=(1-p)*.22;c.fillStyle='#d5d5d2';c.beginPath();c.arc(w*.18+Math.sin(p*5)*4,-h*.48-p*25,4+p*5,0,Math.PI*2);c.fill()}}if(b.hp/b.maxHp<.55){for(let i=0;i<2;i++){const p=(phase*.6+i*.5)%1;c.globalAlpha=(1-p)*.28;c.fillStyle='#1f2022';c.beginPath();c.arc(-w*.12+Math.sin(p*7)*6,-h*.30-p*20,5+p*7,0,Math.PI*2);c.fill()}}c.restore()}
function drawAnimatedBuilding(b,d,img,isEnemy=false){const c=state.ctx,size=d.size||72,scale=b.type==='townCenter'?1.45:(b.type==='house'?1.05:1.12),w=size*scale,h=size*scale*.84,hp=Math.max(0,Math.min(1,(b.hp||0)/(b.maxHp||1))),damageShake=worldAnimationsEnabled()&&hp<.35?Math.sin(performance.now()*.025+(b.id||0))*1.7:0,idlePulse=worldAnimationsEnabled()&&b.complete?1+Math.sin(performance.now()*.0015+(b.id||0))*.006:1;c.save();c.translate(b.x+damageShake,b.y);c.fillStyle='rgba(0,0,0,.35)';c.beginPath();c.ellipse(0,h*.32,w*.40,h*.11,0,0,Math.PI*2);c.fill();c.scale(idlePulse,idlePulse);if(img){c.globalAlpha=b.complete?1:.43;c.drawImage(img,-w/2,-h/2,w,h);c.globalAlpha=1;if(isEnemy){c.globalCompositeOperation='source-atop';c.fillStyle='rgba(150,20,25,.36)';c.fillRect(-w/2,-h/2,w,h);c.globalCompositeOperation='source-over'}}else{c.fillStyle=isEnemy?'#732c2c':d.color||'#765438';c.fillRect(-w*.38,-h*.12,w*.76,h*.44)}c.restore();drawBuildingAnimationDetails(b,d,w,h,isEnemy);c.save();c.translate(b.x,b.y);c.fillStyle='rgba(64,26,22,.9)';c.fillRect(-w*.42,-h*.50,w*.84,7);c.fillStyle=b.complete?(isEnemy?'#d94a43':hp>.5?'#4c9b4b':'#c36c36'):'#c99b45';c.fillRect(-w*.42,-h*.50,w*.84*(b.complete?hp:Math.max(0,Math.min(1,b.progress/100))),7);if(!b.complete){c.fillStyle='#f6e6b8';c.font='bold 11px Georgia';c.textAlign='center';c.fillText(`${Math.floor(b.progress||0)}%`,0,h*.48)}c.restore();state.animationStats.buildings++}

function drawFallbackBuilding(b,d){const c=state.ctx,s=d.size;c.save();c.translate(b.x,b.y);c.fillStyle='rgba(0,0,0,.35)';c.beginPath();c.ellipse(0,s*.42,s*.75,s*.28,0,0,Math.PI*2);c.fill();if(!b.complete){c.strokeStyle='#d6b36a';c.lineWidth=4;c.strokeRect(-s*.55,-s*.35,s*1.1,s*.75);c.fillStyle='rgba(130,88,45,.55)';c.fillRect(-s*.5,-s*.3,s*b.progress/100,s*.65);c.fillStyle='#f6e6b8';c.font='bold 12px Georgia';c.textAlign='center';c.fillText(`${d.label} ${Math.floor(b.progress)}%`,0,s*.62)}else{c.fillStyle=d.color;c.fillRect(-s*.48,-s*.18,s*.96,s*.65);c.fillStyle=b.type==='mill'?'#d6c49c':'#a87a46';c.beginPath();c.moveTo(-s*.6,-s*.18);c.lineTo(0,-s*.72);c.lineTo(s*.6,-s*.18);c.closePath();c.fill();if(b.type==='mill'){c.strokeStyle='#ead9ad';c.lineWidth=5;for(let a=0;a<Math.PI*2;a+=Math.PI/2){c.beginPath();c.moveTo(0,-s*.25);c.lineTo(Math.cos(a)*s*.72,Math.sin(a)*s*.72-s*.25);c.stroke()}}if(b.type==='lumberCamp'){c.strokeStyle='#5a321d';c.lineWidth=7;for(let i=-2;i<=2;i++){c.beginPath();c.moveTo(i*12,-s*.1);c.lineTo(i*12,s*.38);c.stroke()}}c.fillStyle='#f4e2ae';c.font='bold 12px Georgia';c.textAlign='center';c.fillText(d.label,0,s*.7)}const hp=b.hp/b.maxHp;c.fillStyle='#401a16';c.fillRect(-s*.5,-s*.82,s,8);c.fillStyle=hp>.5?'#4c9b4b':'#c36c36';c.fillRect(-s*.5,-s*.82,s*hp,8);c.restore()}
function drawDecor(d){const c=state.ctx;c.save();c.translate(d.x,d.y);if(d.type==='tree'){c.fillStyle='#2a1a0f';c.fillRect(-5,7,10,24);c.fillStyle='#173d22';for(const a of [[0,-16,22],[0,-2,25],[-10,6,18],[12,7,18]]){c.beginPath();c.arc(a[0],a[1],a[2],0,Math.PI*2);c.fill()}c.strokeStyle='rgba(225,190,90,.22)';c.stroke()}else if(d.type==='bush'){c.fillStyle='#4b742f';for(const a of [[-8,0,10],[6,-3,12],[0,7,11]]){c.beginPath();c.arc(a[0],a[1],a[2],0,Math.PI*2);c.fill()}}else if(d.type==='gold'){c.fillStyle='#d6a52e';for(const a of [[-12,5,10],[0,-4,14],[13,6,9]]){c.beginPath();c.moveTo(a[0],a[1]-a[2]);c.lineTo(a[0]+a[2],a[1]+a[2]);c.lineTo(a[0]-a[2],a[1]+a[2]);c.closePath();c.fill()}c.strokeStyle='#fff0a1';c.stroke()}else if(d.type==='stonePile'){c.fillStyle='#777a7f';for(const a of [[-12,5,12],[2,-3,15],[15,7,10]]){c.beginPath();c.arc(a[0],a[1],a[2],0,Math.PI*2);c.fill();c.strokeStyle='#b5b6b8';c.stroke()}}else if(d.type==='bridge'){c.fillStyle='#70492b';c.fillRect(-45,-28,90,56);c.strokeStyle='#c7a46a';c.lineWidth=4;for(let x=-40;x<45;x+=14){c.beginPath();c.moveTo(x,-25);c.lineTo(x,25);c.stroke()}}c.restore()}

const STRATEGIC_POINT_DEFS=[
 {label:'Colina do Norte',px:.30,py:.18,resource:'wood'},
 {label:'Campos do Oeste',px:.16,py:.55,resource:'food'},
 {label:'Ponte Central',px:.50,py:.48,resource:'vision'},
 {label:'Mina do Oriente',px:.82,py:.40,resource:'gold'},
 {label:'Pedreira do Sul',px:.62,py:.82,resource:'stone'}
];
function visibilityIndex(cx,cy){return cy*state.map.cols+cx}
function worldVisibility(wx,wy){if(!state.visibility||!state.map)return 0;const c=worldToCell(wx,wy);return state.visibility[visibilityIndex(c.x,c.y)]||0}
function revealVisibility(wx,wy,radiusTiles){if(!state.visibility)return;const center=worldToCell(wx,wy),r=Math.ceil(radiusTiles);for(let oy=-r;oy<=r;oy++)for(let ox=-r;ox<=r;ox++){if(ox*ox+oy*oy>radiusTiles*radiusTiles)continue;const x=center.x+ox,y=center.y+oy;if(x<0||y<0||x>=state.map.cols||y>=state.map.rows)continue;state.visibility[visibilityIndex(x,y)]=2}}
function initializeTerritory(savedExploration=null,savedPoints=null){const size=state.map.cols*state.map.rows;state.visibility=new Uint8Array(size);if(Array.isArray(savedExploration)&&savedExploration.length===size)savedExploration.forEach((v,i)=>state.visibility[i]=v?1:0);const validSaved=Array.isArray(savedPoints)&&savedPoints.length===STRATEGIC_POINT_DEFS.length;state.strategicPoints=STRATEGIC_POINT_DEFS.map((d,i)=>{const s=validSaved?savedPoints[i]:null,p=nearestPassable(Number(s?.x)||state.map.width*d.px,Number(s?.y)||state.map.height*d.py)||{x:state.map.width*d.px,y:state.map.height*d.py};return{id:i+1,label:d.label,x:p.x,y:p.y,resource:d.resource,owner:['player','enemy'].includes(s?.owner)?s.owner:'neutral',capture:Math.max(-100,Math.min(100,Number(s?.capture)||0))}});state.territoryGrid=new Int8Array(size);state.visibilityTimer=999;state.territoryTimer=999;state.territoryIncomeTimer=0;updateVisibility(1000,true);updateTerritoryGrid();updateTerritoryUI()}
function updateVisibility(dt,force=false){if(!state.visibility||!state.map)return;state.visibilityTimer+=dt;if(!force&&state.visibilityTimer<220)return;state.visibilityTimer=0;for(let i=0;i<state.visibility.length;i++)if(state.visibility[i]===2)state.visibility[i]=1;revealVisibility(state.townCenter.x,state.townCenter.y,6.5);for(const u of state.units){const r=u.type==='archer'?5.3:u.type==='cavalry'?4.8:u.type==='villager'?3.4:4.2;revealVisibility(u.x,u.y,r)}for(const b of state.buildings){if(!b.complete)continue;revealVisibility(b.x,b.y,b.type==='outpost'?7:3.2)}for(const p of state.strategicPoints)if(p.owner==='player')revealVisibility(p.x,p.y,p.resource==='vision'?6.5:4.5);let explored=0;for(const v of state.visibility)if(v>0)explored++;state.territoryStats.explored=Math.round(explored/state.visibility.length*100);updateTerritoryUI()}
function pointPresence(point,side){const list=side==='player'?state.units:state.enemies;let power=0;for(const u of list){if(u.hp<=0)continue;const d=Math.hypot(u.x-point.x,u.y-point.y);if(d<205)power+=u.type==='cavalry'?1.4:u.type==='villager'?.55:1}if(side==='player')for(const b of state.buildings)if(b.complete&&b.type==='outpost'&&Math.hypot(b.x-point.x,b.y-point.y)<280)power+=2;return power}
function updateStrategicPoints(dt){for(const p of state.strategicPoints){const friendly=pointPresence(p,'player'),enemy=pointPresence(p,'enemy'),oldOwner=p.owner;if(friendly>0&&enemy===0)p.capture=Math.min(100,p.capture+dt*.011*(1+Math.min(3,friendly)*.18));else if(enemy>0&&friendly===0)p.capture=Math.max(-100,p.capture-dt*.011*(1+Math.min(3,enemy)*.18));if(p.capture>=100)p.owner='player';else if(p.capture<=-100)p.owner='enemy';else if((oldOwner==='player'&&p.capture<=0)||(oldOwner==='enemy'&&p.capture>=0))p.owner='neutral';if(oldOwner!==p.owner&&p.owner!=='neutral'){if(p.owner==='player')window.VALE_AUDIO?.playSfx?.('territory-capture',{volume:.95,minGap:500});status(`${p.label} agora pertence ${p.owner==='player'?'ao seu reino':'ao inimigo'}`)}}}
function territorySources(side){const out=[];if(side==='player'){out.push({x:state.townCenter.x,y:state.townCenter.y,r:850,w:2});for(const b of state.buildings)if(b.complete)out.push({x:b.x,y:b.y,r:b.type==='outpost'?700:300,w:b.type==='outpost'?1.8:.45});for(const u of state.units)out.push({x:u.x,y:u.y,r:190,w:.32})}else if(state.enemyAI){out.push({x:state.enemyAI.base.x,y:state.enemyAI.base.y,r:850,w:2});for(const b of state.enemyAI.buildings||[])if(b.complete)out.push({x:b.x,y:b.y,r:b.type==='outpost'?650:300,w:b.type==='outpost'?1.7:.45});for(const e of state.enemies)out.push({x:e.x,y:e.y,r:190,w:.34})}for(const p of state.strategicPoints)if(p.owner===side)out.push({x:p.x,y:p.y,r:p.resource==='vision'?620:520,w:1.25});return out}
function sourceInfluence(sources,x,y){let total=0;for(const s of sources){const d=Math.hypot(x-s.x,y-s.y);if(d<s.r)total+=s.w*(1-d/s.r)}return total}
function updateTerritoryGrid(){if(!state.territoryGrid||!state.map)return;const ps=territorySources('player'),es=territorySources('enemy'),ts=state.map.tile;let pc=0,ec=0,nc=0;for(let y=0;y<state.map.rows;y++)for(let x=0;x<state.map.cols;x++){const wx=x*ts+ts/2,wy=y*ts+ts/2,p=sourceInfluence(ps,wx,wy),e=sourceInfluence(es,wx,wy),i=visibilityIndex(x,y);let owner=0;if(p>.12&&p>e*1.08)owner=1;else if(e>.12&&e>p*1.08)owner=-1;state.territoryGrid[i]=owner;if(owner===1)pc++;else if(owner===-1)ec++;else nc++}const total=state.territoryGrid.length;state.territoryStats.player=Math.round(pc/total*100);state.territoryStats.enemy=Math.round(ec/total*100);state.territoryStats.neutral=Math.max(0,100-state.territoryStats.player-state.territoryStats.enemy);state.territoryStats.pointsPlayer=state.strategicPoints.filter(p=>p.owner==='player').length;state.territoryStats.pointsEnemy=state.strategicPoints.filter(p=>p.owner==='enemy').length;updateTerritoryUI()}
function applyTerritoryIncome(){for(const p of state.strategicPoints){if(p.resource==='vision'||p.owner==='neutral')continue;const target=p.owner==='player'?state.stock:state.enemyAI?.stock,cap=p.owner==='player'?state.storage:state.enemyAI?.storage;if(!target||!cap)continue;target[p.resource]=Math.min(cap[p.resource]||9999,(target[p.resource]||0)+2)}updateStockUI()}
function updateTerritory(dt){if(!state.strategicPoints.length)return;updateStrategicPoints(dt);state.territoryTimer+=dt;state.territoryIncomeTimer+=dt;if(state.territoryTimer>=850){state.territoryTimer=0;updateTerritoryGrid()}if(state.territoryIncomeTimer>=1000){state.territoryIncomeTimer-=1000;applyTerritoryIncome()}}
function territoryOwnerLabel(owner){return owner==='player'?'Seu reino':owner==='enemy'?'Reino rival':'Neutro'}
function updateTerritoryUI(){if($('minimapTitle'))$('minimapTitle').textContent=`EXPLORADO ${state.territoryStats.explored||0}% • DOMÍNIO ${state.territoryStats.player||0}%`;if($('btnTerritoryPanel')){$('btnTerritoryPanel').classList.toggle('territory-active',(state.territoryStats.pointsPlayer||0)>0);$('btnTerritoryPanel').dataset.tooltip=`Explorado ${state.territoryStats.explored||0}% • ${state.territoryStats.pointsPlayer||0}/5 pontos`}}
function openTerritoryPanel(){const s=state.territoryStats,rows=state.strategicPoints.map(p=>{const pct=Math.max(0,Math.min(100,(p.capture+100)/2));return`<div class="territory-point-row ${p.owner}"><img src="assets/ui/icons-upgrade/minimap/icon-marker.png" alt=""><div><strong>${p.label}</strong><span>${territoryOwnerLabel(p.owner)} • ${p.resource==='vision'?'visão ampliada':'+2 '+labelResource(p.resource)+'/s'}</span><div class="territory-progress"><i style="width:${pct}%"></i></div></div><b>${Math.round(Math.abs(p.capture))}%</b></div>`}).join('');openModal('Exploração e Controle Territorial',`<div class="territory-panel"><section class="territory-summary"><h3>Domínio do Vale</h3><div class="territory-stat-grid"><div class="territory-stat"><small>Explorado</small><b>${s.explored}%</b></div><div class="territory-stat"><small>Seu domínio</small><b>${s.player}%</b></div><div class="territory-stat"><small>Domínio rival</small><b>${s.enemy}%</b></div><div class="territory-stat"><small>Pontos controlados</small><b>${s.pointsPlayer}/5</b></div></div><p style="font-size:.58rem;color:#a8c3d0;line-height:1.45">Aldeões, tropas, edifícios e postos avançados revelam o mapa. Mantenha unidades próximas dos pontos estratégicos para capturá-los.</p><button class="territory-toggle" id="btnToggleTerritory">${state.showTerritory?'OCULTAR':'MOSTRAR'} CORES TERRITORIAIS</button></section><section class="territory-points"><h3>Pontos estratégicos</h3><div class="territory-point-list">${rows}</div></section></div>`);setTimeout(()=>{const b=$('btnToggleTerritory');if(b)b.onclick=()=>{state.showTerritory=!state.showTerritory;closeModal();status(`Cores territoriais ${state.showTerritory?'ativadas':'ocultadas'}`)}},0)}
function drawStrategicPoints(){const c=state.ctx,img=asset('assets/ui/icons-upgrade/minimap/icon-marker.png');for(const p of state.strategicPoints){const vis=worldVisibility(p.x,p.y);if(!vis)continue;const color=p.owner==='player'?'#58a8f0':p.owner==='enemy'?'#df5350':'#d5b75f';c.save();c.translate(p.x,p.y);c.globalAlpha=vis===2?1:.55;c.fillStyle='rgba(0,0,0,.35)';c.beginPath();c.ellipse(0,27,30,10,0,0,Math.PI*2);c.fill();c.strokeStyle=color;c.lineWidth=4;c.beginPath();c.arc(0,0,30,0,Math.PI*2);c.stroke();if(img)c.drawImage(img,-23,-28,46,46);c.fillStyle=color;c.font='bold 10px Georgia';c.textAlign='center';c.fillText(p.label,0,43);c.restore()}}
function drawTerritoryOverlay(){if(!state.showTerritory||!state.territoryGrid)return;const c=state.ctx,ts=state.map.tile,sc=Math.max(0,Math.floor(state.camera.x/ts)),ec=Math.min(state.map.cols,Math.ceil((state.camera.x+innerWidth/state.camera.zoom)/ts)),sr=Math.max(0,Math.floor(state.camera.y/ts)),er=Math.min(state.map.rows,Math.ceil((state.camera.y+innerHeight/state.camera.zoom)/ts));c.save();for(let y=sr;y<er;y++)for(let x=sc;x<ec;x++){const i=visibilityIndex(x,y);if(!state.visibility[i])continue;const owner=state.territoryGrid[i];if(!owner)continue;c.fillStyle=owner===1?'rgba(42,112,183,.095)':'rgba(181,47,48,.085)';c.fillRect(x*ts,y*ts,ts,ts)}c.restore()}
function drawFogOfWar(){if(!state.visibility)return;const c=state.ctx,ts=state.map.tile,sc=Math.max(0,Math.floor(state.camera.x/ts)-1),ec=Math.min(state.map.cols,Math.ceil((state.camera.x+innerWidth/state.camera.zoom)/ts)+1),sr=Math.max(0,Math.floor(state.camera.y/ts)-1),er=Math.min(state.map.rows,Math.ceil((state.camera.y+innerHeight/state.camera.zoom)/ts)+1);c.save();for(let y=sr;y<er;y++)for(let x=sc;x<ec;x++){const v=state.visibility[visibilityIndex(x,y)];if(v===2)continue;c.fillStyle=v===1?'rgba(3,8,15,.58)':'rgba(1,4,8,.985)';c.fillRect(x*ts,y*ts,ts+1,ts+1)}c.restore()}

function drawTownCenter(){const d={label:'Centro Urbano',size:84,color:'#765438'},img=asset(BUILDING_ICON_PATHS.townCenter),b={id:0,type:'townCenter',x:state.townCenter.x,y:state.townCenter.y,hp:999,maxHp:999,complete:true,progress:100};drawAnimatedBuilding(b,d,img,false)}
function draw(){const c=state.ctx;c.clearRect(0,0,innerWidth,innerHeight);c.save();c.translate(state.shakeX||0,state.shakeY||0);c.scale(state.camera.zoom,state.camera.zoom);c.translate(-state.camera.x,-state.camera.y);const ts=state.map.tile,sc=Math.max(0,Math.floor(state.camera.x/ts)),ec=Math.min(state.map.cols,Math.ceil((state.camera.x+innerWidth/state.camera.zoom)/ts)),sr=Math.max(0,Math.floor(state.camera.y/ts)),er=Math.min(state.map.rows,Math.ceil((state.camera.y+innerHeight/state.camera.zoom)/ts));for(let y=sr;y<er;y++)for(let x=sc;x<ec;x++){const t=state.map.tiles[y][x],src='assets/terrain/terrain-'+({grassLight:'grass-light',grassDark:'grass-dark',dirt:'dirt',stone:'stone-path',water:'water-shallow',rock:'rock'}[t])+'.png',im=state.assets[src];if(im)c.drawImage(im,x*ts,y*ts,ts,ts);else{c.fillStyle=tileColor(t);c.fillRect(x*ts,y*ts,ts,ts)}if(state.showGrid){c.strokeStyle='rgba(255,255,255,.12)';c.strokeRect(x*ts,y*ts,ts,ts)}}drawTerritoryOverlay();drawTownCenter();drawEnemyBase();state.buildings.forEach(drawBuilding);state.map.decor.filter(d=>d.x>=state.camera.x-100&&d.x<=state.camera.x+innerWidth/state.camera.zoom+100&&d.y>=state.camera.y-100&&d.y<=state.camera.y+innerHeight/state.camera.zoom+100).forEach(drawDecor);drawStrategicPoints();drawTradeRoutes();drawNavalRoutes();drawFactionEnclaves();drawNavalPorts();drawCaravans();drawShips();drawNavalMilitary();drawAmphibiousZones();drawCoastalSiegeLayer();drawUrbanSiegeLayer();drawCityAdministrationLayer();drawProvinceNetworkLayer();drawSelectedRoutes();state.units.forEach(drawUnit);state.enemies.filter(e=>worldVisibility(e.x,e.y)===2).forEach(drawEnemy);drawProjectiles();drawEffects();drawFogOfWar();c.restore();drawScreenAtmosphere();if(state.selectionBox)drawSelectionBox();drawMinimap()}
function drawSelectedRoutes(){const c=state.ctx;c.save();c.strokeStyle='rgba(95,180,255,.58)';c.lineWidth=3/state.camera.zoom;c.setLineDash([10/state.camera.zoom,7/state.camera.zoom]);for(const u of state.units){if(!state.selected.has(u.id)||!u.path?.length)continue;c.beginPath();c.moveTo(u.x,u.y);for(let i=u.pathIndex||0;i<u.path.length;i++)c.lineTo(u.path[i].x,u.path[i].y);c.stroke()}c.restore()}
function drawUnit(u){const type=u.type||'villager',img=asset(UNIT_ICON_PATHS[type]||UNIT_ICON_PATHS.villager),size=type==='siegeTower'?92:type==='siegeRam'?84:type==='cavalry'?78:(type==='villager'?58:64);if(img){drawAnimatedUnit(u,img,size,false);return}drawSpriteEntity(null,u.x,u.y,size,size,{selected:state.selected.has(u.id),progressBar:{value:(u.hp||0)/(u.maxHp||1),color:'#4c9b4b'},badgeText:type==='villager'?String(u.id):(u.badge||type)})}
function drawEnemy(e){const img=asset(UNIT_ICON_PATHS[e.type]||UNIT_ICON_PATHS.infantry),size=e.type==='siegeTower'?92:e.type==='siegeRam'?84:e.type==='cavalry'?78:64;if(img){drawAnimatedUnit(e,img,size,true);return}drawSpriteEntity(null,e.x,e.y,size,size,{progressBar:{value:e.hp/e.maxHp,color:'#d64a44'},badgeText:'INIMIGO'})}
function nearestLivingEnemy(u){let best=null,dist=Infinity;for(const e of state.enemies){if(e.hp<=0)continue;const d=Math.hypot(e.x-u.x,e.y-u.y);if(d<dist){dist=d;best=e}}return best?{enemy:best,dist}:null}
function nearestLivingFriendly(e){let best=null,dist=Infinity;for(const u of state.units){if(u.hp<=0)continue;const d=Math.hypot(u.x-e.x,u.y-e.y);if(d<dist){dist=d;best=u}}return best?{unit:best,dist}:null}
function damageTarget(attacker,target,isEnemyAttacker=false){const raw=Math.max(1,(attacker.attack||5)-(target.armor||0));window.VALE_AUDIO?.setCombat?.(true);window.VALE_AUDIO?.playSfx?.(attacker.type==='archer'?'arrow-shot':attacker.type==='cavalry'?'cavalry-charge':'sword-hit',{volume:isEnemyAttacker?.65:.82,minGap:attacker.type==='archer'?90:70,rate:.92+Math.random()*.16});target.hp-=raw;state.effects.push({x:target.x,y:target.y,life:420,maxLife:420,type:'impact',damage:raw,color:isEnemyAttacker?'#ef6457':'#f3d17b'});state.effects.push({x:target.x+(Math.random()-.5)*18,y:target.y-8,life:620,maxLife:620,type:'damage',text:'-'+raw,color:isEnemyAttacker?'#ff8b79':'#ffe29b'});triggerCameraShake(raw>15?7:3);if(attacker.type==='archer'){state.projectiles.push({x:attacker.x,y:attacker.y,tx:target.x,ty:target.y,life:260,maxLife:260,color:isEnemyAttacker?'#ff6a55':'#f5d67d'})}if(target.hp<=0){target.hp=0;window.VALE_AUDIO?.playSfx?.('unit-death',{volume:.8,minGap:160,rate:.9+Math.random()*.12});state.effects.push({x:target.x,y:target.y,life:850,maxLife:850,type:'death',color:isEnemyAttacker?'#9d3c35':'#d9bd74'});if(isEnemyAttacker){state.defeats++;state.selected.delete(target.id)}else{state.kills++;attacker.xp=(attacker.xp||0)+25;if(attacker.xp>=attacker.level*100){attacker.xp-=attacker.level*100;attacker.level++;attacker.maxHp+=12;attacker.hp=attacker.maxHp;attacker.attack+=2;status(`${attacker.name||attacker.type} subiu para o nível ${attacker.level}`)}}}}
function updateCombat(dt){const rivalHostile=isRivalHostile();for(const u of state.units){u.cooldown=Math.max(0,(u.cooldown||0)-dt);if(u.hp<=0)continue;let target=null;if(u.task?.kind==='attack')target=state.enemies.find(e=>e.id===u.task.enemyId&&e.hp>0);if(!rivalHostile){if(u.task?.kind==='attack'){u.task=null;u.target=null;u.state='idle';clearRoute(u)}continue}if(!target&&u.type!=='villager'){const n=nearestLivingEnemy(u);if(n&&n.dist<220)target=n.enemy}if(!target)continue;const d=Math.hypot(target.x-u.x,target.y-u.y),range=(u.range||25)+(target.r||20);if(d>range){const p=nearestPassable(target.x,target.y);if(p)setDestination(u,p,false);u.state='engaging'}else{u.target=null;clearRoute(u);u.state='fighting';if(u.cooldown<=0){damageTarget(u,target,false);u.cooldown=u.type==='archer'?1050:u.type==='cavalry'?850:780}}}
for(const e of state.enemies){if(!rivalHostile){e.state='guard';e.target=null;clearRoute(e);continue}e.cooldown=Math.max(0,(e.cooldown||0)-dt);if(e.hp<=0)continue;const n=nearestLivingFriendly(e);if(!n)continue;const aggro=n.dist<520||e.state==='engaged';if(!aggro)continue;e.state='engaged';const target=n.unit,d=n.dist,range=(e.range||25)+(target.r||20);if(d>range){setDestination(e,nearestPassable(target.x,target.y),false);navigateEntity(e,dt,state.enemies)}else if(e.cooldown<=0){damageTarget(e,target,true);e.cooldown=e.type==='archer'?1150:e.type==='cavalry'?930:850}}
state.units=state.units.filter(u=>u.hp>0);state.enemies=state.enemies.filter(e=>e.hp>0);state.projectiles.forEach(p=>p.life-=dt);state.projectiles=state.projectiles.filter(p=>p.life>0);state.effects.forEach(f=>f.life-=dt);state.effects=state.effects.filter(f=>f.life>0);if($('combatStats'))$('combatStats').textContent=`Abates: ${state.kills} • Baixas: ${state.defeats} • Inimigos: ${state.enemies.length}`;window.VALE_AUDIO?.setCombat?.(state.units.some(u=>u.state==='fighting'||u.state==='engaging')||state.enemies.some(e=>e.state==='engaged'))}
function drawProjectiles(){const c=state.ctx;for(const p of state.projectiles){const t=1-p.life/p.maxLife,x=p.x+(p.tx-p.x)*t,y=p.y+(p.ty-p.y)*t;c.save();c.fillStyle=p.color;c.shadowColor=p.color;c.shadowBlur=8;c.beginPath();c.arc(x,y,4,0,Math.PI*2);c.fill();c.restore()}}
function drawEffects(){const c=state.ctx;for(const f of state.effects){if(f.type==='era'){const t=1-f.life/f.maxLife,r=40+t*260;c.save();c.globalAlpha=Math.max(0,f.life/f.maxLife);c.strokeStyle=f.color||'#e2bd62';c.lineWidth=8*(1-t)+2;c.beginPath();c.arc(f.x,f.y,r,0,Math.PI*2);c.stroke();c.fillStyle='rgba(255,231,166,.15)';c.beginPath();c.arc(f.x,f.y,r*.65,0,Math.PI*2);c.fill();c.restore();continue}c.save();c.globalAlpha=Math.max(0,f.life/f.maxLife);if(f.type==='damage'){c.fillStyle=f.color||'#ffcc8a';c.font='bold 16px Georgia';c.textAlign='center';c.fillText(String(f.text||''),f.x,f.y-(1-f.life/f.maxLife)*28)}else if(f.type==='death'){const t=1-f.life/f.maxLife;c.translate(f.x,f.y);c.rotate(t*.8);c.strokeStyle=f.color||'#d9bd74';c.lineWidth=4*(1-t)+1;for(let i=0;i<5;i++){const a=i*Math.PI*2/5+t*1.4;c.beginPath();c.moveTo(Math.cos(a)*8,Math.sin(a)*5);c.lineTo(Math.cos(a)*(22+t*28),Math.sin(a)*(14+t*20));c.stroke()}c.fillStyle='rgba(30,20,15,'+(0.35*(1-t))+')';c.beginPath();c.ellipse(0,12,22+t*16,8+t*5,0,0,Math.PI*2);c.fill()}else{c.fillStyle=f.color||'#f2d36f';c.beginPath();c.arc(f.x,f.y,8+(1-f.life/f.maxLife)*18,0,Math.PI*2);c.fill()}c.restore()}}
function drawSelectionBox(){const b=state.selectionBox,c=state.ctx;c.save();c.fillStyle='rgba(74,140,220,.18)';c.strokeStyle='rgba(190,220,255,.95)';c.setLineDash([7,5]);c.fillRect(b.x,b.y,b.w,b.h);c.strokeRect(b.x,b.y,b.w,b.h);c.restore()}
function drawMinimap(){const c=state.mctx,w=state.minimap.width,h=state.minimap.height,sx=w/state.map.width,sy=h/state.map.height;c.clearRect(0,0,w,h);c.fillStyle='#01050a';c.fillRect(0,0,w,h);const step=2;for(let y=0;y<state.map.rows;y+=step)for(let x=0;x<state.map.cols;x+=step){const v=state.visibility?.[visibilityIndex(x,y)]||0;if(!v)continue;c.globalAlpha=v===2?1:.42;c.fillStyle=tileColor(state.map.tiles[y][x]);c.fillRect(x*state.map.tile*sx,y*state.map.tile*sy,state.map.tile*step*sx+1,state.map.tile*step*sy);const owner=state.territoryGrid?.[visibilityIndex(x,y)]||0;if(state.showTerritory&&owner){c.globalAlpha=.25;c.fillStyle=owner===1?'#3284d2':'#c23e3e';c.fillRect(x*state.map.tile*sx,y*state.map.tile*sy,state.map.tile*step*sx+1,state.map.tile*step*sy)}}c.globalAlpha=1;for(const r of state.map.resources){if(r.amount<=0||worldVisibility(r.x,r.y)===0)continue;c.fillStyle=r.type==='wood'?'#173f20':r.type==='gold'?'#d3a431':r.type==='stone'?'#aaa':'#8eb74a';c.fillRect(r.x*sx-1,r.y*sy-1,3,3)}for(const p of state.strategicPoints){if(worldVisibility(p.x,p.y)===0)continue;c.fillStyle=p.owner==='player'?'#62b0ff':p.owner==='enemy'?'#f04d4d':'#e2c167';c.beginPath();c.arc(p.x*sx,p.y*sy,3.5,0,Math.PI*2);c.fill()}c.fillStyle='#c89b45';state.buildings.forEach(b=>c.fillRect(b.x*sx-2,b.y*sy-2,4,4));c.fillStyle='#ffffff';c.fillRect(state.townCenter.x*sx-3,state.townCenter.y*sy-3,6,6);state.units.forEach(u=>{c.fillStyle=(u.type&&u.type!=='villager')?'#65a7ff':'#e5bd58';c.fillRect(u.x*sx-1,u.y*sy-1,3,3)});(state.enemyAI?.buildings||[]).forEach(b=>{if(worldVisibility(b.x,b.y)!==2)return;c.fillStyle='#a72828';c.fillRect(b.x*sx-3,b.y*sy-3,6,6)});state.enemies.forEach(e=>{if(worldVisibility(e.x,e.y)!==2)return;c.fillStyle='#ef4141';c.fillRect(e.x*sx-2,e.y*sy-2,4,4)});for(const f of (state.tradeWorld?.factions||[])){if(!f.discovered&&worldVisibility(f.x,f.y)===0)continue;const n=nationById(f.id);c.fillStyle=f.status==='war'?'#d9534f':f.status==='alliance'?'#65d189':f.status==='trade'?'#e2c35e':'#9caeb6';c.fillRect(f.x*sx-3,f.y*sy-3,6,6);c.strokeStyle=n.color;c.strokeRect(f.x*sx-4,f.y*sy-4,8,8)}for(const cv of state.caravans||[]){if(worldVisibility(cv.x,cv.y)===0)continue;c.fillStyle='#ffd36a';c.beginPath();c.arc(cv.x*sx,cv.y*sy,2.5,0,Math.PI*2);c.fill()}for(const p of (state.navalWorld?.ports||[])){if(!p.discovered&&worldVisibility(p.x,p.y)===0)continue;c.fillStyle=p.capturedByPlayer?'#62d998':'#62c5e8';c.fillRect(p.x*sx-3,p.y*sy-2,6,4)}for(const s of state.ships||[]){if(worldVisibility(s.x,s.y)===0)continue;c.fillStyle='#7ce2ef';c.beginPath();c.arc(s.x*sx,s.y*sy,2.7,0,Math.PI*2);c.fill()}for(const r of (state.navalWorld?.raiders||[])){if(r.hp<=0||worldVisibility(r.x,r.y)===0)continue;c.fillStyle='#e5584e';c.beginPath();c.arc(r.x*sx,r.y*sy,2.8,0,Math.PI*2);c.fill()}for(const f of state.navalFleet||[]){c.fillStyle='#4fb8f0';c.fillRect(f.x*sx-2.5,f.y*sy-2.5,5,5)}for(const e of (state.navalMilitary?.enemyFleet||[])){if(worldVisibility(e.x,e.y)===0)continue;c.fillStyle='#ff5048';c.fillRect(e.x*sx-2.5,e.y*sy-2.5,5,5)}for(const d of (state.coastalSiege?.enemyDefenses||[])){if(d.hp<=0||worldVisibility(d.x,d.y)===0)continue;c.fillStyle=d.type==='tower'?'#ff784f':'#b84d45';c.fillRect(d.x*sx-2,d.y*sy-2,4,4)}c.strokeStyle='#fff3bf';c.lineWidth=2;c.strokeRect(state.camera.x*sx,state.camera.y*sy,innerWidth/state.camera.zoom*sx,innerHeight/state.camera.zoom*sy)}
let last=performance.now();function loop(now){const dt=Math.min(40,now-last);last=now;if(state.active==='game'){update(dt);draw()}state.raf=requestAnimationFrame(loop)}

