function setBuildMode(type){if(!BUILDING_DEFS[type])return;const minEra=BUILDING_MIN_ERA[type]||0;if(state.eraIndex<minEra){status(`${BUILDING_DEFS[type].label} exige ${eraIndexLabel(minEra)}`);updateEraUI();return}state.buildMode=type;state.repairMode=false;state.buildMenuOpen=false;updateBuildModeHelp();const d=BUILDING_DEFS[type];status(`Construir ${d.label}: ${costText(d.cost)}. Toque em terreno livre.`)}
function updateBuildModeHelp(){const e=$('buildModeHelp');if(!e)return;e.textContent=state.buildMode?`Modo construção: ${BUILDING_DEFS[state.buildMode].label}`:state.repairMode?'Modo reparo: selecione edifício':'Modo construção: desativado';updateContextHUD()}
function costText(cost){return Object.entries(cost).map(([k,v])=>`${labelResource(k)} ${v}`).join(' • ')}
function canAfford(cost){return Object.entries(cost).every(([k,v])=>(state.stock[k]||0)>=v)}
function spend(cost){Object.entries(cost).forEach(([k,v])=>state.stock[k]-=v);updateStockUI()}
function buildingAt(wx,wy){return state.buildings.slice().reverse().find(b=>Math.hypot(b.x-wx,b.y-wy)<(BUILDING_DEFS[b.type]?.size||55)*.7)}
function footprintFree(wx,wy,size){if(!isPassable(wx,wy))return false;if(Math.hypot(wx-state.townCenter.x,wy-state.townCenter.y)<140)return false;if(state.buildings.some(b=>Math.hypot(wx-b.x,wy-b.y)<(size+(BUILDING_DEFS[b.type]?.size||55))*.72))return false;return !state.map.resources.some(r=>r.amount>0&&Math.hypot(wx-r.x,wy-r.y)<size*.9)}
function placeBuildingAtScreen(sx,sy){const type=state.buildMode,d=BUILDING_DEFS[type];if(!d)return;const w=screenToWorld(sx,sy),p=nearestPassable(w.x,w.y);if(!p||!footprintFree(p.x,p.y,d.size)){status('Local inválido ou ocupado');return}if((type==='harbor'||type==='shipyard'||type==='coastalFort'||type==='coastalWall'||type==='beachTower')&&!hasAdjacentWater(p.x,p.y)){status(`${d.label} deve ser construído junto à água`);return}if(!canAfford(d.cost)){status(`Recursos insuficientes para ${d.label}: ${costText(d.cost)}`);return}spend(d.cost);const eraHp=Math.round(d.maxHp*effectiveBuildingHpMultiplier()),b={id:state.buildingSeq++,type,x:p.x,y:p.y,progress:0,hp:Math.round(eraHp*.15),maxHp:eraHp,complete:false,assigned:[],builtEra:state.eraIndex,gateOpen:type==='cityGate'?false:undefined};state.buildings.push(b);assignBuilders(b);state.buildMode=null;updateBuildModeHelp();window.VALE_AUDIO?.playSfx?.('construction',{volume:.85,minGap:180});status(`Fundação de ${d.label} posicionada`)}
function assignBuilders(b){const sel=state.units.filter(u=>state.selected.has(u.id)&&(u.type==='villager'||!u.type));const fallback=state.units.filter(u=>u.type==='villager'||!u.type).slice(0,2);const builders=(sel.length?sel:fallback).slice(0,5);b.assigned=builders.map(u=>u.id);builders.forEach((u,i)=>{u.task={kind:'build',buildingId:b.id};u.state='toBuild';setDestination(u,nearestPassable(b.x+Math.cos(i*1.7)*55,b.y+Math.sin(i*1.7)*55),true)})}
function repairBuildingAtScreen(sx,sy){const w=screenToWorld(sx,sy),b=buildingAt(w.x,w.y);if(!b){status('Nenhum edifício selecionado para reparar');return}if(!b.complete||b.hp>=b.maxHp){status('Este edifício não precisa de reparo');return}const selected=state.units.filter(u=>state.selected.has(u.id)&&(u.type==='villager'||!u.type));if(!selected.length){status('Selecione aldeões para reparar');return}b.assigned=selected.slice(0,5).map(u=>u.id);selected.slice(0,5).forEach((u,i)=>{u.task={kind:'repair',buildingId:b.id};u.state='toRepair';setDestination(u,nearestPassable(b.x+Math.cos(i*1.7)*55,b.y+Math.sin(i*1.7)*55),true)});state.repairMode=false;updateBuildModeHelp();status(`Reparo iniciado em ${BUILDING_DEFS[b.type].label}`)}
function updateConstruction(dt){for(const b of state.buildings){const d=BUILDING_DEFS[b.type];for(const id of (b.assigned||[])){const u=state.units.find(x=>x.id===id);if(!u)continue;const dist=Math.hypot(u.x-b.x,u.y-b.y);if((u.state==='toBuild'||u.state==='toRepair')&&dist<85){u.target=null;u.state=u.task?.kind==='repair'?'repairing':'building'}if(u.state==='building'&&!b.complete){b.progress+=dt/(d.buildTime/effectiveConstructionMultiplier())*100;b.hp=Math.min(b.maxHp,Math.max(b.hp,b.maxHp*b.progress/100));if(b.progress>=100){b.progress=100;b.complete=true;b.hp=b.maxHp;u.task=null;u.state='idle';u.target=null;recalculateEconomy();updateStockUI();state.effects.push({type:'era',x:b.x,y:b.y,life:1100,maxLife:1100,color:'#e6c56f'});triggerCameraShake(4);window.VALE_AUDIO?.playSfx?.('building-complete',{volume:.95,minGap:280});if(state.urbanSiege){if(b.type==='cityWall')state.urbanSiege.stats.wallsBuilt++;if(b.type==='cityGate')state.urbanSiege.stats.gatesBuilt++;if(b.type==='cityTower')state.urbanSiege.stats.towersBuilt++;}status(`${d.label} concluído`) }}else if(u.state==='repairing'&&b.complete){if((state.stock.wood||0)>0&&b.hp<b.maxHp){const add=Math.min(b.maxHp-b.hp,dt*.018);b.hp+=add;state.stock.wood=Math.max(0,state.stock.wood-add*.08);updateStockUI()}if(b.hp>=b.maxHp||state.stock.wood<=0){b.hp=Math.min(b.maxHp,b.hp);u.task=null;u.state='idle';u.target=null}}}}
}
function drawHarbor(b){const c=state.ctx,s=BUILDING_DEFS.harbor.size,water=adjacentWaterPoint(b.x,b.y),wave=worldAnimationsEnabled()?Math.sin(state.animationClock*.004)*3:0;c.save();c.translate(b.x,b.y);c.fillStyle='rgba(0,0,0,.32)';c.beginPath();c.ellipse(0,28,s*.72,18,0,0,Math.PI*2);c.fill();c.fillStyle=b.complete?'#70482a':'rgba(112,72,42,.45)';c.fillRect(-s*.58,-12,s*1.16,48);c.strokeStyle='#d8b56c';c.lineWidth=4;for(let x=-s*.48;x<s*.5;x+=14){c.beginPath();c.moveTo(x,-10);c.lineTo(x,35);c.stroke()}c.fillStyle='#274f73';c.fillRect(-8,-50,16,42);c.fillStyle='#f2d38b';c.beginPath();c.moveTo(8,-48);c.lineTo(45,-28+wave);c.lineTo(8,-14);c.closePath();c.fill();c.fillStyle='#f5e3ac';c.font='bold 10px Georgia';c.textAlign='center';c.fillText(b.complete?'PORTO':'EM CONSTRUÇÃO',0,53);const hp=Math.max(0,Math.min(1,b.hp/b.maxHp));c.fillStyle='#461c18';c.fillRect(-s*.48,-62,s*.96,7);c.fillStyle=hp>.5?'#5ebd70':'#dc644f';c.fillRect(-s*.48,-62,s*.96*hp,7);c.restore();if(water&&b.complete){c.save();c.strokeStyle='rgba(99,201,235,.5)';c.lineWidth=3;c.setLineDash([8,6]);c.beginPath();c.moveTo(b.x,b.y);c.lineTo(water.x,water.y);c.stroke();c.restore()}}
