function enemyAIBuildDecision(){const ai=state.enemyAI,done=ai.buildings.filter(b=>b.complete),alive=state.enemies.length+ai.queue.length;const count=t=>done.filter(b=>b.type===t).length;if(ai.buildings.some(b=>!b.complete))return;if(alive>=ai.popCap-2&&enemyAIStartBuilding('house'))return;if(!count('barracks')&&enemyAIStartBuilding('barracks'))return;if(!count('lumberCamp')&&enemyAIStartBuilding('lumberCamp'))return;if(!count('mill')&&enemyAIStartBuilding('mill'))return;if((ai.eraIndex||0)>=1&&!count('archeryRange')&&enemyAIStartBuilding('archeryRange'))return;if((ai.eraIndex||0)>=2&&!count('stable')&&enemyAIStartBuilding('stable'))return;if(ai.wave>=2&&!count('storehouse'))enemyAIStartBuilding('storehouse')}
