function updateEnemyAI(dt){if(!state.enemyAI||!state.enemyAI.base)return;const ai=state.enemyAI;updateEnemyAIEra(dt);updateEnemyAITechnology(dt);updateEnemyAICivilization(dt);updateEnemyAIConstruction(dt);updateEnemyAIEconomy(dt);updateEnemyAIProduction(dt);updateEnemyAIRetreats(dt);if(!isRivalHostile()){ai.phase='trégua';ai.lastOrder='Tratado de não agressão ativo';updateEnemyAIUI();return}ai.decisionTimer+=dt;ai.attackTimer+=dt;ai.stallTimer=(ai.stallTimer||0)+dt;const diff=currentDifficulty();if(ai.decisionTimer>=diff.decisionMs){ai.decisionTimer=0;assessAIDirector();const threat=playerThreatNearEnemyBase();ai.underAttack=false;if(!enemyAIDefend(threat)){enemyAIBuildDecision();enemyAIQueueUnit();if(ai.phase==='defesa')ai.phase='expansão'}}let attackThreshold=Math.max(22000,diff.attackMs-ai.wave*2600);if(ai.directorMode==='pressão')attackThreshold*=.88;if(ai.directorMode==='recuperação')attackThreshold*=1.12;if(ai.attackTimer>=attackThreshold||ai.stallTimer>=attackThreshold*1.45){if(launchEnemyWave()){if(ai.stallTimer>=attackThreshold*1.45){state.aiDirector.forcedAttacks++;ai.lastOrder='Ataque anti-estagnação lançado'}ai.attackTimer=0;ai.stallTimer=0}else ai.attackTimer=Math.max(0,ai.attackTimer-6000)}updateEnemyAIUI()}
