function eraRequirementStatus(req){const completed=state.buildings.filter(b=>b.complete);let current=0;if(req.type==='building')current=completed.filter(b=>b.type===req.key).length;else if(req.type==='population')current=currentPopulation();else if(req.type==='army')current=state.units.filter(u=>u.type&&u.type!=='villager').length;else if(req.type==='gathered')current=Math.floor(state.totalGathered);return{ok:current>=req.count,current,target:req.count,label:req.label}}
