function technologyCanResearch(t){if(!t||hasTech(t.key)||state.techResearch)return false;if(state.eraIndex<t.era)return false;if(t.requires&&!hasTech(t.requires))return false;return eraCostAffordable(adjustedTechCost(t.cost))}
