function formatTechCost(cost){return Object.entries(cost||{}).map(([k,v])=>`<i>${labelResource(k)} ${v}</i>`).join('')}
function openTechPanel(){const active=state.techResearch;let html=`<div class="tech-tree-shell"><div class="tech-tree-summary"><span>Era disponível: <b>${currentEra().label}</b></span><span>Concluídas: <b>${state.technologies.length}/${TECH_DEFS.length}</b></span><span>${active?`Pesquisa: <b>${techByKey(active.key)?.label||active.key} ${Math.floor(active.progress/active.time*100)}%</b>`:'Laboratório disponível'}</span></div><div class="tech-tree-grid">`;for(const [cat,meta] of Object.entries(TECH_CATEGORIES)){html+=`<section class="tech-column ${cat}"><div class="tech-column-title"><img src="${meta.icon}" alt="${meta.label}"><strong>${meta.label}</strong></div>`;for(const t of TECH_DEFS.filter(x=>x.category===cat)){const researched=hasTech(t.key),isActive=active?.key===t.key,locked=state.eraIndex<t.era||(t.requires&&!hasTech(t.requires)),progress=isActive?Math.min(100,active.progress/active.time*100):0;html+=`<article class="tech-node ${researched?'researched':''} ${locked?'locked':''} ${isActive?'active':''}"><img src="${t.icon}" alt="${t.label}"><div class="tech-node-copy"><strong>${t.label}</strong><span>${t.description}</span><small>${eraIndexLabel(t.era)}${t.requires?' • após '+techByKey(t.requires).label:''}</small></div>${isActive?`<div class="tech-progress-shell"><div class="tech-progress-fill" style="width:${progress}%"></div></div>`:''}<div class="tech-node-status"><div class="tech-cost-mini">${formatTechCost(adjustedTechCost(t.cost))}</div><button class="tech-research-button" data-tech="${t.key}" ${technologyCanResearch(t)?'':'disabled'}>${technologyStatusLabel(t)}</button></div></article>`}html+='</section>'}html+='</div></div>';openModal('Árvore Tecnológica',html);setTimeout(()=>document.querySelectorAll('.tech-research-button[data-tech]').forEach(b=>b.onclick=()=>startTechResearch(b.dataset.tech)),0)}
function startTechResearch(key){const t=techByKey(key);if(!t)return;if(hasTech(key)){status('Tecnologia já concluída');return}if(state.techResearch){status('Já existe uma pesquisa tecnológica em andamento');return}if(state.eraIndex<t.era){status(`${t.label} exige ${eraIndexLabel(t.era)}`);return}if(t.requires&&!hasTech(t.requires)){status(`Pesquise ${techByKey(t.requires)?.label||t.requires} primeiro`);return}const adjustedCost=adjustedTechCost(t.cost);if(!eraCostAffordable(adjustedCost)){status('Recursos insuficientes para esta tecnologia');return}spend(adjustedCost);state.techResearch={key:t.key,progress:0,time:adjustedTechTime(t.time),startedAt:Date.now()};closeModal();updateTechUI();status(`Pesquisa tecnológica iniciada: ${t.label}`)}
