function openDiplomacyPanel(){if(!state.diplomacy)initializeDiplomacy();renderDiplomacyPanel();$('diplomacyOverlay')?.classList.remove('hidden');$('diplomacyOverlay')?.setAttribute('aria-hidden','false');window.VALE_AUDIO?.playSfx?.('ui-click',{category:'ui',volume:.55,minGap:100})}
