function playerShipyard(){return state.buildings.find(b=>b.complete&&b.type==='shipyard')||null}
function playerFleetDock(){const yard=playerShipyard(),harbor=playerHarbor();return yard?adjacentWaterPoint(yard.x,yard.y):(harbor?adjacentWaterPoint(harbor.x,harbor.y):null)}
function rivalNavalPort(){const rival=state.diplomacy?.factions?.find(f=>f.isRival);return rival?state.navalWorld?.ports?.find(p=>p.id===rival.id)||null:null}
function navalFleetCap(){return 3+state.eraIndex*2+state.buildings.filter(b=>b.complete&&b.type==='shipyard').length*4}
function normalizeWarship(raw={},enemy=false){const d=NAVAL_UNIT_DEFS[raw.type]||NAVAL_UNIT_DEFS.patrolGalley,maxHp=Math.max(1,Number(raw.maxHp)||d.hp),capacity=Math.max(0,Number(raw.capacity)||Number(d.capacity)||0);return{...raw,id:Number(raw.id)||state.navalFleetSeq++,type:d.key,label:raw.label||d.label,faction:enemy?'enemy':'player',x:Number(raw.x)||0,y:Number(raw.y)||0,hp:Math.max(0,Number(raw.hp)||maxHp),maxHp,attack:Math.max(0,Number.isFinite(Number(raw.attack))?Number(raw.attack):d.attack),range:Math.max(0,Number.isFinite(Number(raw.range))?Number(raw.range):d.range),armor:Math.max(0,Number(raw.armor)||d.armor),speed:Math.max(.5,Number(raw.speed)||d.speed),cooldown:Math.max(0,Number(raw.cooldown)||0),order:raw.order||'patrol',patrolDir:Number(raw.patrolDir)||1,target:null,route:[],routeIndex:0,combatTarget:null,respawnAt:Number(raw.respawnAt)||0,capacity,passengers:Array.isArray(raw.passengers)?raw.passengers.map(p=>({...p,target:null,path:null,task:null})):[],amphibiousState:raw.amphibiousState||'idle',landingPoint:raw.landingPoint||null,lastLandAt:Number(raw.lastLandAt)||0}}
function defaultAmphibious(){return{version:1,enemyInvasionTimer:0,coastalDefenseTimer:0,stats:{landings:0,troopsLanded:0,enemyLandings:0,invasionsRepelled:0,transportsLost:0,troopsLostAtSea:0},lastWarningAt:0}}
function defaultNavalMilitary(){return{version:2,stats:{kills:0,losses:0,battles:0,escorts:0,blockadeSeconds:0,enemyBlockadeSeconds:0},queue:[],queueProgress:0,command:'patrol',playerBlockaded:false,rivalBlockaded:false,blockadeTick:0,enemySpawnTimer:0,enemyFleet:[],amphibious:defaultAmphibious()}}
function normalizeNavalMilitary(saved){const base=defaultNavalMilitary();if(!saved||typeof saved!=='object')return base;base.stats={...base.stats,...(saved.stats||{})};base.queue=Array.isArray(saved.queue)?saved.queue.filter(q=>NAVAL_UNIT_DEFS[q.type]):[];base.queueProgress=Math.max(0,Number(saved.queueProgress)||0);base.command=['escort','patrol','blockade','return','landing'].includes(saved.command)?saved.command:'patrol';base.blockadeTick=Math.max(0,Number(saved.blockadeTick)||0);base.enemySpawnTimer=Math.max(0,Number(saved.enemySpawnTimer)||0);base.enemyFleet=Array.isArray(saved.enemyFleet)?saved.enemyFleet:[];base.amphibious={...defaultAmphibious(),...(saved.amphibious||{}),stats:{...defaultAmphibious().stats,...(saved.amphibious?.stats||{})}};return base}
function initializeNavalMilitary(saved=null){state.navalMilitary=normalizeNavalMilitary(saved);state.amphibious=state.navalMilitary.amphibious;state.navalFleetSeq=1;state.navalFleet=(saved?.fleet||[]).map(s=>normalizeWarship(s,false));state.navalFleetSeq=Math.max(1,...state.navalFleet.map(s=>s.id||0),...state.navalMilitary.enemyFleet.map(s=>Number(s.id)||0))+1;state.navalMilitary.enemyFleet=state.navalMilitary.enemyFleet.map(s=>normalizeWarship(s,true));state.navalQueue=state.navalMilitary.queue.map(q=>({...q}));state.navalProductionProgress=state.navalMilitary.queueProgress;state.navalCommand=state.navalMilitary.command;for(const s of [...state.navalFleet,...state.navalMilitary.enemyFleet]){s.target=null;s.route=[];s.routeIndex=0;s.combatTarget=null}updateNavalMilitaryUI()}
function serializeNavalMilitary(){if(!state.navalMilitary)return null;const cleanPassenger=p=>({name:p.name,type:p.type,hp:p.hp,maxHp:p.maxHp,attack:p.attack,range:p.range,armor:p.armor,xp:p.xp,level:p.level,variant:p.variant,unitLabel:p.unitLabel,badge:p.badge,speed:p.speed,r:p.r});const clean=s=>({id:s.id,type:s.type,label:s.label,x:s.x,y:s.y,hp:s.hp,maxHp:s.maxHp,attack:s.attack,range:s.range,armor:s.armor,speed:s.speed,cooldown:s.cooldown,order:s.order,patrolDir:s.patrolDir,capacity:s.capacity,passengers:(s.passengers||[]).map(cleanPassenger),amphibiousState:s.amphibiousState,landingPoint:s.landingPoint,lastLandAt:s.lastLandAt});return{version:2,stats:{...state.navalMilitary.stats},queue:state.navalQueue.map(q=>({...q})),queueProgress:state.navalProductionProgress,command:state.navalCommand,playerBlockaded:!!state.navalMilitary.playerBlockaded,rivalBlockaded:!!state.navalMilitary.rivalBlockaded,blockadeTick:state.navalMilitary.blockadeTick||0,enemySpawnTimer:state.navalMilitary.enemySpawnTimer||0,amphibious:{...state.amphibious,stats:{...state.amphibious?.stats}},fleet:state.navalFleet.map(clean),enemyFleet:state.navalMilitary.enemyFleet.map(clean)}}
function queueNavalUnit(type){const d=NAVAL_UNIT_DEFS[type],yard=playerShipyard(),dock=playerFleetDock();if(!d)return false;if(state.eraIndex<d.era){status(`${d.label} exige ${eraIndexLabel(d.era)}`);return false}if(!yard||!dock){status('Construa um Estaleiro Real junto à água para produzir navios militares');return false}if(state.navalFleet.length+state.navalQueue.length>=navalFleetCap()){status(`Limite naval atingido (${navalFleetCap()})`);return false}if(state.navalQueue.length>=5){status('Fila do estaleiro cheia');return false}if(!canAfford(d.cost)){status(`Recursos insuficientes: ${costText(d.cost)}`);return false}spend(d.cost);state.navalQueue.push({type:d.key,label:d.label,time:d.time,cost:{...d.cost}});state.navalProductionProgress=0;window.VALE_AUDIO?.playSfx?.('ui-confirm',{category:'ui',volume:.65,minGap:160});status(`${d.label} adicionada à fila naval`);updateNavalMilitaryUI();return true}
function spawnNavalUnit(type,enemy=false){const d=NAVAL_UNIT_DEFS[type]||NAVAL_UNIT_DEFS.patrolGalley,source=enemy?(rivalNavalPort()||{x:state.map.width*.8,y:(state.map.seaStart+2)*state.map.tile}):(playerFleetDock());if(!source)return false;const water=nearestWater(source.x+(enemy?-55:55),source.y+((state.navalFleetSeq%3)-1)*36)||source,ship=normalizeWarship({id:state.navalFleetSeq++,type:d.key,label:d.label,x:water.x,y:water.y,hp:d.hp,maxHp:d.hp,attack:d.attack,range:d.range,armor:d.armor,speed:d.speed,order:enemy?'blockade':state.navalCommand},enemy);if(enemy)state.navalMilitary.enemyFleet.push(ship);else state.navalFleet.push(ship);state.effects.push({x:ship.x,y:ship.y,life:900,maxLife:900,type:'era',color:enemy?'#e85b54':'#62c8ed'});return true}
function updateNavalProduction(dt){if(!state.navalQueue.length){state.navalProductionProgress=0;return}if(!playerShipyard()||!playerFleetDock())return;const q=state.navalQueue[0];state.navalProductionProgress+=dt;if(state.navalProductionProgress>=q.time){state.navalProductionProgress=0;state.navalQueue.shift();spawnNavalUnit(q.type,false);status(`${q.label} lançada ao mar`);window.VALE_AUDIO?.playSfx?.('building-complete',{volume:.72,minGap:240})}}
function setNavalFleetOrder(order){if(!['escort','patrol','blockade','return'].includes(order))return;state.navalCommand=order;if(state.navalMilitary)state.navalMilitary.command=order;for(const s of state.navalFleet){s.order=order;s.target=null;s.route=[];s.combatTarget=null}const labels={escort:'Escolta de mercantes',patrol:'Patrulha costeira',blockade:'Bloqueio do porto rival',return:'Retorno ao estaleiro'};status(`${labels[order]} aplicada a ${state.navalFleet.length} navio(s)`);updateNavalMilitaryUI()}
function nearestNavalTarget(ship,targets,maxDistance=700){let best=null,dist=maxDistance;for(const t of targets){if(!t||t.hp<=0)continue;const d=Math.hypot(t.x-ship.x,t.y-ship.y);if(d<dist){dist=d;best=t}}return best}
function navalMoveTo(ship,dest){if(!dest)return false;if(!ship.target||Math.hypot(ship.target.x-dest.x,ship.target.y-dest.y)>80)setWaterDestination(ship,dest,true);return true}
function navalStrike(attacker,target,dt){if(!attacker||!target||attacker.hp<=0||target.hp<=0)return false;attacker.cooldown=Math.max(0,(attacker.cooldown||0)-dt);const d=Math.hypot(target.x-attacker.x,target.y-attacker.y);if(d>attacker.range)return false;if(attacker.cooldown>0)return true;const def=NAVAL_UNIT_DEFS[attacker.type]||NAVAL_UNIT_DEFS.patrolGalley;let damage=Math.max(1,Math.round(attacker.attack-(target.armor||0)*.72));if(attacker.type==='fireShip'&&d<58){damage=Math.round(attacker.attack*1.8);attacker.hp=0;state.effects.push({x:attacker.x,y:attacker.y,life:1200,maxLife:1200,type:'death',color:'#ff9b45'})}target.hp-=damage;attacker.cooldown=def.cooldown;state.effects.push({x:target.x,y:target.y-18,life:650,maxLife:650,type:'damage',text:`-${damage}`,color:'#ffd184'});state.effects.push({x:(attacker.x+target.x)/2,y:(attacker.y+target.y)/2,life:420,maxLife:420,type:'impact',color:'#f3d18b'});window.VALE_AUDIO?.playSfx?.('impact',{volume:.42,minGap:100});return true}
function friendlyNavalHostiles(){return[...(state.navalMilitary?.enemyFleet||[]).filter(s=>s.hp>0),...(state.navalWorld?.raiders||[]).filter(s=>s.hp>0)]}
function updateFriendlyWarship(ship,dt){if(ship.hp<=0)return;if(ship.type==='transportShip'){updateTransportShip(ship,dt,false);return}const dock=playerFleetDock(),rival=rivalNavalPort(),hostiles=friendlyNavalHostiles();let target=nearestNavalTarget(ship,hostiles,ship.order==='escort'?520:760);if(target){ship.combatTarget=target;if(Math.hypot(target.x-ship.x,target.y-ship.y)>ship.range*.82)navalMoveTo(ship,target);else{ship.target=null;ship.route=[]}navalStrike(ship,target,dt)}else{ship.combatTarget=null;if(ship.order==='escort'){const merchant=state.ships.filter(s=>s.phase==='outbound'&&s.hp>0).sort((a,b)=>Math.hypot(a.x-ship.x,a.y-ship.y)-Math.hypot(b.x-ship.x,b.y-ship.y))[0];if(merchant){navalMoveTo(ship,{x:merchant.x+32,y:merchant.y+24});state.navalMilitary.stats.escorts=Math.max(state.navalMilitary.stats.escorts,1)}else if(dock)navalMoveTo(ship,dock)}else if(ship.order==='blockade'&&rival){navalMoveTo(ship,{x:rival.x+(ship.id%3-1)*70,y:rival.y-90})}else if(ship.order==='return'&&dock){navalMoveTo(ship,dock);if(Math.hypot(ship.x-dock.x,ship.y-dock.y)<90)ship.hp=Math.min(ship.maxHp,ship.hp+dt*.018)}else{const seaY=(state.map.seaStart+2+(ship.id%2))*state.map.tile,patrol={x:ship.patrolDir>0?state.map.width-state.map.tile*2:state.map.tile*2,y:seaY};if(!ship.target)navalMoveTo(ship,patrol);if(ship.target&&Math.hypot(ship.x-ship.target.x,ship.y-ship.target.y)<30){ship.patrolDir*=-1;ship.target=null;ship.route=[]}}}navigateWater(ship,dt)}
function updateEnemyWarship(ship,dt){if(ship.hp<=0)return;if(ship.type==='transportShip'){updateTransportShip(ship,dt,true);return}const rival=rivalNavalPort(),dock=playerDockWaterPoint();if(!isRivalHostile()){if(rival)navalMoveTo(ship,rival);navigateWater(ship,dt);return}const targets=[...state.ships.filter(s=>s.phase==='outbound'&&s.hp>0),...state.navalFleet.filter(s=>s.hp>0)],target=nearestNavalTarget(ship,targets,850);if(target){ship.combatTarget=target;if(Math.hypot(target.x-ship.x,target.y-ship.y)>ship.range*.82)navalMoveTo(ship,target);else{ship.target=null;ship.route=[]}navalStrike(ship,target,dt)}else if(dock){ship.combatTarget=null;navalMoveTo(ship,{x:dock.x+(ship.id%3-1)*80,y:dock.y+100})}navigateWater(ship,dt)}
function ensureEnemyNavalFleet(dt){if(!state.navalMilitary||state.eraIndex<1||!isRivalHostile()||state.coastalSiege?.port?.owner==='player')return;state.navalMilitary.enemySpawnTimer+=dt;const cap=Math.min(6,2+Math.floor(state.eraIndex*1.4)+Math.floor(difficultyRank(state.difficulty)/2)),alive=state.navalMilitary.enemyFleet.filter(s=>s.hp>0).length,interval=state.navalMilitary.rivalBlockaded?52000:32000;if(alive<cap&&state.navalMilitary.enemySpawnTimer>=interval){state.navalMilitary.enemySpawnTimer=0;const types=state.eraIndex>=2?['patrolGalley','warGalley','patrolGalley']:['patrolGalley'];spawnNavalUnit(types[Math.floor(Math.random()*types.length)],true)}}
function updateNavalBlockades(dt){const dock=playerDockWaterPoint(),rival=rivalNavalPort(),enemy=state.navalMilitary.enemyFleet.filter(s=>s.hp>0),friendly=state.navalFleet.filter(s=>s.hp>0);state.navalMilitary.playerBlockaded=!!(dock&&enemy.filter(s=>Math.hypot(s.x-dock.x,s.y-dock.y)<300).length>=2);state.navalMilitary.rivalBlockaded=state.coastalSiege?.port?.owner==='player'||!!(rival&&friendly.filter(s=>s.order==='blockade'&&Math.hypot(s.x-rival.x,s.y-rival.y)<310).length>=2);if(state.navalMilitary.playerBlockaded)state.navalMilitary.stats.enemyBlockadeSeconds+=dt/1000;if(state.navalMilitary.rivalBlockaded){state.navalMilitary.stats.blockadeSeconds+=dt/1000;state.navalMilitary.blockadeTick+=dt;if(state.navalMilitary.blockadeTick>=15000){state.navalMilitary.blockadeTick=0;state.stock.gold=Math.min(state.storage.gold||9999,(state.stock.gold||0)+6);updateStockUI();diplomacyNotify('Bloqueio naval pressiona o porto rival: +6 ouro')}}else state.navalMilitary.blockadeTick=0}
function updateNavalMilitary(dt){if(!state.navalMilitary||!state.map)return;updateNavalProduction(dt);ensureEnemyNavalFleet(dt);for(const s of state.navalFleet)updateFriendlyWarship(s,dt);for(const s of state.navalMilitary.enemyFleet)updateEnemyWarship(s,dt);const friendly=[];for(const s of state.navalFleet){if(s.hp>0)friendly.push(s);else{state.navalMilitary.stats.losses++;if(s.type==='transportShip'){const lost=(s.passengers||[]).length;state.amphibious.stats.transportsLost++;state.amphibious.stats.troopsLostAtSea+=lost;state.defeats+=lost;diplomacyNotify(`Transporte perdido no mar: ${lost} tropa(s).`,'warning')}state.effects.push({x:s.x,y:s.y,life:1100,maxLife:1100,type:'death',color:'#68c9ed'})}}state.navalFleet=friendly;const enemy=[];for(const s of state.navalMilitary.enemyFleet){if(s.hp>0)enemy.push(s);else{if(!s.retired)state.navalMilitary.stats.kills++;if(!s.retired&&s.type==='transportShip'&&(s.passengers||[]).length){state.amphibious.stats.invasionsRepelled++;diplomacyNotify('Invasão costeira repelida antes do desembarque.')}state.effects.push({x:s.x,y:s.y,life:1100,maxLife:1100,type:'death',color:'#ef665d'})}}state.navalMilitary.enemyFleet=enemy;updateNavalBlockades(dt);state.navalCombatTimer+=dt;if(state.navalCombatTimer>=700){state.navalCombatTimer=0;updateNavalMilitaryUI()}}
function drawWarship(ship,enemy=false){if(enemy&&worldVisibility(ship.x,ship.y)===0)return;const d=NAVAL_UNIT_DEFS[ship.type]||NAVAL_UNIT_DEFS.patrolGalley,label=ship.type==='patrolGalley'?'PATRULHA':ship.type==='warGalley'?'GUERRA':ship.type==='fireShip'?'FOGO':'TRANSP.';drawShipShape(ship.x,ship.y,enemy?'#e65d55':d.color,label,ship.hp,ship.maxHp,enemy);const c=state.ctx;c.save();c.translate(ship.x,ship.y);if(ship.type==='transportShip'){c.fillStyle=enemy?'#ff9a91':'#ffe3a2';c.fillRect(-22,2,44,11);c.fillStyle='#172332';c.font='bold 9px Georgia';c.textAlign='center';c.fillText(`${(ship.passengers||[]).length}/${ship.capacity||0}`,0,11);if(ship.order==='landing'||ship.order==='enemyLanding'){c.strokeStyle=enemy?'#ff665e':'#8be2aa';c.lineWidth=3;c.beginPath();c.arc(0,4,40,0,Math.PI*2);c.stroke()}}else{c.fillStyle=enemy?'#ef6b61':'#f4d27f';const guns=ship.type==='warGalley'?3:ship.type==='fireShip'?1:2;for(let i=0;i<guns;i++){c.beginPath();c.arc(-14+i*14,8,3,0,Math.PI*2);c.fill()}if(ship.order==='escort'&&!enemy){c.strokeStyle='rgba(102,220,181,.75)';c.lineWidth=3;c.beginPath();c.arc(0,4,38,0,Math.PI*2);c.stroke()}}c.restore()}
function drawNavalMilitary(){for(const s of state.navalFleet)drawWarship(s,false);for(const s of state.navalMilitary?.enemyFleet||[])drawWarship(s,true)}
function transportShips(enemy=false){const fleet=enemy?(state.navalMilitary?.enemyFleet||[]):state.navalFleet;return fleet.filter(s=>s.type==='transportShip'&&s.hp>0)}
function passengerCount(enemy=false){return transportShips(enemy).reduce((sum,s)=>sum+(s.passengers||[]).length,0)}
function transportReservedSlots(ship){return state.units.filter(u=>u.task?.kind==='embark'&&u.task.transportId===ship.id).length}
function cleanPassenger(u){return{name:u.name,type:u.type,hp:u.hp,maxHp:u.maxHp,attack:u.attack,range:u.range,armor:u.armor,xp:u.xp,level:u.level,variant:u.variant,unitLabel:u.unitLabel,badge:u.badge,speed:u.speed,r:u.r}}
function embarkDockLand(){const yard=playerShipyard()||playerHarbor();return yard?nearestPassable(yard.x,yard.y):null}
function prepareEmbarkSelectedTroops(){const dock=embarkDockLand(),transports=transportShips(false);if(!dock||!transports.length){status('Produza um Navio de Transporte e mantenha o Estaleiro ativo.');return false}const troops=state.units.filter(u=>state.selected.has(u.id)&&u.type&&u.type!=='villager');if(!troops.length){status('Selecione tropas terrestres para embarcar.');return false}let assigned=0;for(const u of troops){const ship=transports.find(s=>(s.passengers?.length||0)+transportReservedSlots(s)<(s.capacity||0));if(!ship)break;u.task={kind:'embark',transportId:ship.id};u.state='toEmbark';setDestination(u,dock,true);assigned++}status(assigned?`${assigned} tropa(s) marchando para o embarque.`:'Transportes sem capacidade disponível.');return assigned>0}
function processEmbarkOrders(){const dock=embarkDockLand();if(!dock)return;const loaded=[];for(const u of state.units){if(u.task?.kind!=='embark')continue;const ship=state.navalFleet.find(s=>s.id===u.task.transportId&&s.type==='transportShip'&&s.hp>0);if(!ship){u.task=null;u.state='idle';continue}if(Math.hypot(u.x-dock.x,u.y-dock.y)<95&&(ship.passengers||[]).length<(ship.capacity||0)){ship.passengers.push(cleanPassenger(u));loaded.push(u.id);state.selected.delete(u.id);ship.amphibiousState='loaded'}}if(loaded.length){state.units=state.units.filter(u=>!loaded.includes(u.id));updateStockUI();status(`${loaded.length} tropa(s) embarcada(s).`)}}
function amphibiousLandingTarget(enemy=false){const x=enemy?(playerHarbor()?.x||state.townCenter.x):(rivalNavalPort()?.x||state.map.width*.78),landY=(state.map.seaStart-1.4)*state.map.tile,waterY=(state.map.seaStart+.5)*state.map.tile;return{land:nearestPassable(x,landY)||nearestPassable(x,state.map.height*.72),water:nearestWater(x,waterY)}}
function launchAmphibiousLanding(){const loaded=transportShips(false).filter(s=>(s.passengers||[]).length);if(!loaded.length){status('Nenhum transporte possui tropas embarcadas.');return false}const target=amphibiousLandingTarget(false);if(!target.water){status('Nenhuma praia de desembarque encontrada.');return false}for(const s of loaded){s.order='landing';s.amphibiousState='sailing';s.landingPoint=target;setWaterDestination(s,target.water,true)}state.navalCommand='landing';status(`${loaded.length} transporte(s) iniciaram a invasão costeira.`);return true}
function recallAmphibiousTransports(){for(const s of transportShips(false)){s.order='return';s.amphibiousState='returning';s.target=null;s.route=[]}status('Transportes retornando ao Estaleiro Real.')}
function restorePlayerPassengers(ship,land){const selected=[];let offset=0;for(const p of ship.passengers||[]){const pos=nearestPassable(land.x+Math.cos(offset*1.3)*55,land.y+Math.sin(offset*1.3)*55)||land,id=Math.max(0,...state.units.map(u=>u.id))+1,u=normalizeUnit({...p,id,x:pos.x,y:pos.y,target:null,task:null,state:'idle'});state.units.push(u);state.selected.add(u.id);selected.push(u);offset++}state.amphibious.stats.landings++;state.amphibious.stats.troopsLanded+=selected.length;ship.passengers=[];ship.amphibiousState='returning';ship.order='return';ship.target=null;ship.route=[];ship.lastLandAt=Date.now();state.effects.push({x:land.x,y:land.y,life:1200,maxLife:1200,type:'era',color:'#7ee0a2'});status(`${selected.length} tropa(s) desembarcaram na costa rival.`);updateStockUI()}
function spawnEnemyLandingTroops(ship,land){let count=0;for(const p of ship.passengers||[]){const d=MILITARY_DEFS[p.type]||MILITARY_DEFS.infantry,pos=nearestPassable(land.x+Math.cos(count*1.4)*60,land.y+Math.sin(count*1.4)*60)||land,e=normalizeEnemy({id:state.enemySeq++,type:p.type,name:`Invasor costeiro ${state.enemySeq}`,x:pos.x,y:pos.y,hp:d.hp*currentDifficulty().aiCombat,maxHp:d.hp*currentDifficulty().aiCombat,attack:d.attack*currentDifficulty().aiCombat,range:d.range,armor:p.type==='cavalry'?4:p.type==='infantry'?3:1,state:'engaged'});e.home={...land};e.aiOrder='attack';state.enemies.push(e);count++}state.amphibious.stats.enemyLandings++;ship.passengers=[];ship.amphibiousState='returning';ship.order='return';ship.target=null;ship.route=[];ship.lastLandAt=Date.now();state.effects.push({x:land.x,y:land.y,life:1200,maxLife:1200,type:'era',color:'#ef675d'});diplomacyNotify(`Invasão costeira: ${count} tropa(s) inimiga(s) desembarcaram!`,'warning')}
function updateTransportShip(ship,dt,enemy=false){const target=amphibiousLandingTarget(enemy),home=enemy?rivalNavalPort():playerFleetDock();if(enemy&&!isRivalHostile()){ship.order='return';ship.amphibiousState='returning'}if((ship.order==='landing'||ship.order==='enemyLanding')&&(ship.passengers||[]).length){if(target.water){if(!ship.target)navalMoveTo(ship,target.water);navigateWater(ship,dt);if(Math.hypot(ship.x-target.water.x,ship.y-target.water.y)<72){if(enemy)spawnEnemyLandingTroops(ship,target.land);else restorePlayerPassengers(ship,target.land)}}return}if(ship.order==='return'||!(ship.passengers||[]).length){if(home){navalMoveTo(ship,home);navigateWater(ship,dt);if(Math.hypot(ship.x-home.x,ship.y-home.y)<80){ship.target=null;ship.route=[];ship.amphibiousState=(ship.passengers||[]).length?'loaded':'idle';ship.hp=Math.min(ship.maxHp,ship.hp+dt*.02);if(enemy&&!(ship.passengers||[]).length){ship.retired=true;ship.hp=0}}}return}if(home){navalMoveTo(ship,home);navigateWater(ship,dt)}}
function spawnEnemyAmphibiousTransport(){const rival=rivalNavalPort();if(!rival||transportShips(true).some(s=>(s.passengers||[]).length))return false;const rank=difficultyRank(state.difficulty),count=Math.min(8,3+rank+Math.floor(state.eraIndex/2)),types=[];for(let i=0;i<count;i++)types.push({type:state.eraIndex>=3&&i===count-1?'siegeTower':state.eraIndex>=2&&i===count-2?'siegeRam':state.eraIndex>=2&&i%4===3?'cavalry':i%3===2?'archer':'infantry'});const d=NAVAL_UNIT_DEFS.transportShip,water=nearestWater(rival.x,rival.y)||rival,ship=normalizeWarship({id:state.navalFleetSeq++,type:'transportShip',x:water.x,y:water.y,hp:d.hp*(1+rank*.08),maxHp:d.hp*(1+rank*.08),armor:d.armor+Math.floor(rank/2),speed:d.speed,order:'enemyLanding',amphibiousState:'sailing',passengers:types},true);state.navalMilitary.enemyFleet.push(ship);diplomacyNotify('Batedores avistaram uma frota de invasão aproximando-se da costa!','warning');return true}
function updateEnemyAmphibiousInvasions(dt){if(!state.amphibious||state.eraIndex<1||!isRivalHostile())return;state.amphibious.enemyInvasionTimer+=dt;const interval=Math.max(42000,98000-difficultyRank(state.difficulty)*11000-state.eraIndex*7000);if(state.amphibious.enemyInvasionTimer>=interval){state.amphibious.enemyInvasionTimer=0;spawnEnemyAmphibiousTransport()}}
function updateCoastalDefense(dt){const targets=[...(state.navalMilitary?.enemyFleet||[]),...(state.navalWorld?.raiders||[])].filter(s=>s.hp>0);for(const fort of state.buildings.filter(b=>b.complete&&b.type==='coastalFort')){fort.defenseCooldown=Math.max(0,(fort.defenseCooldown||0)-dt);let target=null,dist=430;for(const s of targets){const d=Math.hypot(s.x-fort.x,s.y-fort.y);if(d<dist){dist=d;target=s}}if(target&&fort.defenseCooldown<=0){const damage=24+state.eraIndex*5;target.hp-=damage;fort.defenseCooldown=1250;state.effects.push({x:target.x,y:target.y-14,life:650,maxLife:650,type:'damage',text:`-${damage}`,color:'#ffe09b'});state.effects.push({x:(fort.x+target.x)/2,y:(fort.y+target.y)/2,life:420,maxLife:420,type:'impact',color:'#e8cf92'});window.VALE_AUDIO?.playSfx?.('impact',{volume:.48,minGap:170})}}}
function updateAmphibious(dt){if(!state.amphibious)return;processEmbarkOrders();updateEnemyAmphibiousInvasions(dt);updateCoastalDefense(dt);state.amphibiousTimer+=dt;if(state.amphibiousTimer>=650){state.amphibiousTimer=0;updateAmphibiousUI()}}
function drawAmphibiousZones(){const c=state.ctx;for(const enemy of [false,true]){const t=amphibiousLandingTarget(enemy);if(!t?.land||worldVisibility(t.land.x,t.land.y)===0)continue;c.save();c.globalAlpha=.32;c.strokeStyle=enemy?'#ef665d':'#7be1a1';c.lineWidth=4/state.camera.zoom;c.setLineDash([10/state.camera.zoom,8/state.camera.zoom]);c.beginPath();c.arc(t.land.x,t.land.y,75,0,Math.PI*2);c.stroke();c.restore()}}
function updateAmphibiousUI(){const friendly=transportShips(false),enemy=transportShips(true),cargo=passengerCount(false),stats=state.amphibious?.stats||defaultAmphibious().stats;if($('amphibiousTransportStat'))$('amphibiousTransportStat').textContent=String(friendly.length);if($('amphibiousCargoStat'))$('amphibiousCargoStat').textContent=String(cargo);if($('amphibiousLandingsStat'))$('amphibiousLandingsStat').textContent=`${stats.landings||0}/${stats.enemyLandings||0}`;if($('amphibiousThreatStat'))$('amphibiousThreatStat').textContent=enemy.length?'INVASÃO AVISTADA':'COSTA SEGURA';if($('navalQueueText')&&friendly.some(s=>s.amphibiousState==='sailing'))$('navalQueueText').textContent=`Desembarque em andamento • ${cargo} tropas`}
function updateNavalMilitaryUI(){const n=state.navalMilitary||defaultNavalMilitary(),fleet=state.navalFleet.length,enemy=n.enemyFleet?.filter(s=>s.hp>0).length||0,cap=navalFleetCap(),q=state.navalQueue[0];if($('navalFleetStat'))$('navalFleetStat').textContent=`${fleet}/${cap}`;if($('navalEnemyFleetStat'))$('navalEnemyFleetStat').textContent=String(enemy);if($('navalBlockadeStat'))$('navalBlockadeStat').textContent=n.playerBlockaded?'SOB BLOQUEIO':n.rivalBlockaded?'RIVAL BLOQUEADO':'LIVRE';if($('navalCombatStat'))$('navalCombatStat').textContent=`${n.stats.kills||0}/${n.stats.losses||0}`;if($('navalQueueText'))$('navalQueueText').textContent=q?`${q.label} • ${state.navalQueue.length} na fila`:'Fila naval vazia';if($('navalQueueProgress'))$('navalQueueProgress').style.width=q?`${Math.min(100,state.navalProductionProgress/q.time*100)}%`:'0%';document.querySelectorAll('.naval-order').forEach(b=>b.classList.toggle('active',b.dataset.order===state.navalCommand));document.querySelectorAll('.naval-train').forEach(b=>{const d=NAVAL_UNIT_DEFS[b.dataset.ship],locked=!d||state.eraIndex<d.era;b.disabled=locked;b.classList.toggle('era-locked',locked)});if($('diplomacyHudIncome')&&n.playerBlockaded)$('diplomacyHudIncome').textContent='Porto sob bloqueio naval';updateAmphibiousUI()}


function defaultCoastalSiege(){return{version:1,port:{factionId:null,owner:'enemy',progress:0,fortificationHp:950,maxFortificationHp:950,contested:false,capturedAt:0},enemyDefenses:[],stats:{wallsBuilt:0,towersBuilt:0,siegeUnitsTrained:0,portsCaptured:0,portsLost:0,defensesDestroyed:0,enemySiegeLandings:0},towerTimer:0,captureTimer:0,enemyCounterTimer:0}}
function normalizeCoastalSiege(saved){const base=defaultCoastalSiege(),src=saved&&typeof saved==='object'?saved:{};base.port={...base.port,...(src.port||{})};base.port.progress=Math.max(0,Math.min(100,Number(base.port.progress)||0));base.port.fortificationHp=Math.max(0,Number(base.port.fortificationHp)||base.port.maxFortificationHp);base.stats={...base.stats,...(src.stats||{})};base.enemyDefenses=Array.isArray(src.enemyDefenses)?src.enemyDefenses.map((d,i)=>({...d,id:Number(d.id)||i+1,hp:Math.max(0,Number(d.hp)||Number(d.maxHp)||500),maxHp:Math.max(1,Number(d.maxHp)||500)})):[];return base}
function serializeCoastalSiege(){if(!state.coastalSiege)return null;return{version:1,port:{...state.coastalSiege.port},enemyDefenses:state.coastalSiege.enemyDefenses.map(d=>({...d})),stats:{...state.coastalSiege.stats},towerTimer:state.coastalSiege.towerTimer||0,captureTimer:state.coastalSiege.captureTimer||0,enemyCounterTimer:state.coastalSiege.enemyCounterTimer||0}}
function rivalPortLandPoint(){const port=rivalNavalPort();if(!port||!state.map)return null;return nearestPassable(port.x,(state.map.seaStart-1.35)*state.map.tile)||nearestPassable(port.x,port.y-state.map.tile*3)}
function initializeCoastalSiege(saved=null){state.coastalSiege=normalizeCoastalSiege(saved);const rival=rivalNavalPort();if(rival&&!state.coastalSiege.port.factionId)state.coastalSiege.port.factionId=rival.id;if(rival)rival.capturedByPlayer=state.coastalSiege.port.owner==='player';if(!state.coastalSiege.enemyDefenses.length){const land=rivalPortLandPoint();if(land){const defs=[['wall',-150,18],['wall',-55,0],['wall',55,0],['wall',150,18],['tower',-112,-88],['tower',112,-88]];state.coastalSiege.enemyDefenses=defs.map((d,i)=>{const pos=nearestPassable(land.x+d[1],land.y+d[2])||land;return{id:i+1,type:d[0],x:pos.x,y:pos.y,hp:d[0]==='tower'?620:780,maxHp:d[0]==='tower'?620:780,cooldown:0}})}}updateCoastalSiegeUI();updateUrbanSiegeUI()}
function locateRivalPort(){const p=rivalPortLandPoint();if(!p){status('Porto rival indisponível.');return}state.camera.x=p.x-innerWidth/(2*state.camera.zoom);state.camera.y=p.y-innerHeight/(2*state.camera.zoom);clamp();status('Câmera posicionada no porto rival.')}
function coastalFriendlyTroops(point,radius=190){return state.units.filter(u=>u.hp>0&&u.type!=='villager'&&Math.hypot(u.x-point.x,u.y-point.y)<=radius)}
function coastalEnemyTroops(point,radius=190){return state.enemies.filter(e=>e.hp>0&&Math.hypot(e.x-point.x,e.y-point.y)<=radius)}
function nearestEnemyCoastalDefense(u){let best=null,dist=Infinity;for(const d of state.coastalSiege?.enemyDefenses||[]){if(d.hp<=0)continue;const dd=Math.hypot(d.x-u.x,d.y-u.y);if(dd<dist){dist=dd;best=d}}return best?{defense:best,dist}:null}
function damageCoastalDefense(attacker,defense,mult=1){const siege=attacker.type==='siegeRam'?2.5:1,raw=Math.max(2,Math.round((attacker.attack||8)*siege*mult));defense.hp=Math.max(0,defense.hp-raw);attacker.cooldown=attacker.type==='siegeRam'?1350:900;state.effects.push({x:defense.x,y:defense.y,life:620,maxLife:620,type:'damage',text:`-${raw}`,color:'#ffe29b'});window.VALE_AUDIO?.playSfx?.('impact',{volume:.62,minGap:140});if(defense.hp<=0){state.coastalSiege.stats.defensesDestroyed++;state.effects.push({x:defense.x,y:defense.y,life:900,maxLife:900,type:'death',color:'#d8b36b'});diplomacyNotify('Uma defesa do porto rival foi destruída.')}}
function updateSiegeRams(dt){if(!state.coastalSiege)return;const land=rivalPortLandPoint();for(const u of state.units.filter(x=>x.type==='siegeRam'&&x.hp>0)){u.cooldown=Math.max(0,(u.cooldown||0)-dt);const target=nearestEnemyCoastalDefense(u);if(target){if(target.dist>58){setDestination(u,nearestPassable(target.defense.x,target.defense.y),false);u.state='engaging'}else if(u.cooldown<=0){u.target=null;clearRoute(u);u.state='fighting';damageCoastalDefense(u,target.defense)}}else if(land&&state.coastalSiege.port.fortificationHp>0){const d=Math.hypot(u.x-land.x,u.y-land.y);if(d>72)setDestination(u,land,false);else if(u.cooldown<=0){const raw=Math.max(12,Math.round(u.attack*2.2));state.coastalSiege.port.fortificationHp=Math.max(0,state.coastalSiege.port.fortificationHp-raw);u.cooldown=1450;state.effects.push({x:land.x,y:land.y,life:620,maxLife:620,type:'damage',text:`-${raw}`,color:'#ffe29b'})}}}
for(const e of state.enemies.filter(x=>['siegeRam','siegeTower'].includes(x.type)&&x.hp>0)){e.cooldown=Math.max(0,(e.cooldown||0)-dt);let target=null,dist=Infinity;for(const b of state.buildings.filter(b=>b.complete&&['coastalWall','beachTower','coastalFort','harbor','shipyard','cityWall','cityGate','cityTower'].includes(b.type))){const d=Math.hypot(e.x-b.x,e.y-b.y);if(d<dist){dist=d;target=b}}if(!target)continue;if(dist>65){setDestination(e,nearestPassable(target.x,target.y),false);e.state='engaged'}else if(e.cooldown<=0){const raw=Math.max(10,Math.round((e.attack||45)*2));target.hp=Math.max(0,target.hp-raw);e.cooldown=1500;state.effects.push({x:target.x,y:target.y,life:620,maxLife:620,type:'damage',text:`-${raw}`,color:'#ff8b79'});if(target.hp<=0)diplomacyNotify(`${BUILDING_DEFS[target.type]?.label||'Defesa'} destruída pelo cerco inimigo!`,'warning')}}state.buildings=state.buildings.filter(b=>b.hp>0)}
function updateBeachTowers(dt){if(!state.coastalSiege)return;for(const tower of state.buildings.filter(b=>b.complete&&b.type==='beachTower')){tower.defenseCooldown=Math.max(0,(tower.defenseCooldown||0)-dt);let target=null,dist=330;for(const e of state.enemies){const d=Math.hypot(e.x-tower.x,e.y-tower.y);if(e.hp>0&&d<dist){dist=d;target=e}}for(const s of [...(state.navalMilitary?.enemyFleet||[]),...(state.navalWorld?.raiders||[])]){const d=Math.hypot(s.x-tower.x,s.y-tower.y);if(s.hp>0&&d<dist){dist=d;target=s}}if(target&&tower.defenseCooldown<=0){const damage=18+state.eraIndex*4;target.hp-=damage;tower.defenseCooldown=1150;state.effects.push({x:target.x,y:target.y-10,life:550,maxLife:550,type:'damage',text:`-${damage}`,color:'#ffe09b'});window.VALE_AUDIO?.playSfx?.('arrow-shot',{volume:.46,minGap:120})}}
for(const tower of state.coastalSiege.enemyDefenses.filter(d=>d.type==='tower'&&d.hp>0)){tower.cooldown=Math.max(0,(tower.cooldown||0)-dt);let target=null,dist=300;for(const u of state.units){const d=Math.hypot(u.x-tower.x,u.y-tower.y);if(u.hp>0&&d<dist){dist=d;target=u}}if(target&&tower.cooldown<=0){const damage=15+Math.floor(state.eraIndex*2);target.hp-=damage;tower.cooldown=1250;state.effects.push({x:target.x,y:target.y-8,life:550,maxLife:550,type:'damage',text:`-${damage}`,color:'#ff8b79'})}}}
function updatePortCapture(dt){const c=state.coastalSiege,land=rivalPortLandPoint();if(!c||!land)return;const friendly=coastalFriendlyTroops(land),enemy=coastalEnemyTroops(land),defensesAlive=c.enemyDefenses.some(d=>d.hp>0);c.port.contested=!!(friendly.length&&enemy.length);if(c.port.owner==='enemy'){if(friendly.length&&!enemy.length&&!defensesAlive&&c.port.fortificationHp<=0){c.port.progress=Math.min(100,c.port.progress+dt*(.0035+Math.min(5,friendly.length)*.00045));if(c.port.progress>=100){c.port.owner='player';c.port.capturedAt=Date.now();c.stats.portsCaptured++;const port=rivalNavalPort();if(port)port.capturedByPlayer=true;state.stock.gold=Math.min(state.storage.gold||9999,(state.stock.gold||0)+200);diplomacyNotify('Porto rival conquistado! Reforços navais inimigos interrompidos.');window.VALE_AUDIO?.playSfx?.('territory-capture',{volume:.9,minGap:400});updateStockUI()}}else if(!friendly.length)c.port.progress=Math.max(0,c.port.progress-dt*.001)}else{if(enemy.length&&!friendly.length){c.port.progress=Math.max(0,c.port.progress-dt*.003);if(c.port.progress<=0){c.port.owner='enemy';c.port.fortificationHp=Math.round(c.port.maxFortificationHp*.45);c.stats.portsLost++;const port=rivalNavalPort();if(port)port.capturedByPlayer=false;diplomacyNotify('O rival retomou seu porto marítimo!','warning')}}else c.port.progress=Math.min(100,c.port.progress+dt*.0005);state.coastalSiege.captureTimer+=dt;if(state.coastalSiege.captureTimer>=12000){state.coastalSiege.captureTimer=0;state.stock.gold=Math.min(state.storage.gold||9999,(state.stock.gold||0)+5);state.stock.wood=Math.min(state.storage.wood||9999,(state.stock.wood||0)+4);updateStockUI()}}}
function updateCoastalSiege(dt){if(!state.coastalSiege||!state.map)return;updateSiegeRams(dt);updateBeachTowers(dt);updatePortCapture(dt);state.coastalSiegeTimer+=dt;if(state.coastalSiegeTimer>=650){state.coastalSiegeTimer=0;updateCoastalSiegeUI()}}
function drawCoastalSiegeLayer(){if(!state.coastalSiege)return;const c=state.ctx;for(const d of state.coastalSiege.enemyDefenses){if(d.hp<=0||worldVisibility(d.x,d.y)===0)continue;c.save();c.translate(d.x,d.y);c.globalAlpha=worldVisibility(d.x,d.y)===2?1:.45;if(d.type==='tower'){c.fillStyle='#733c35';c.fillRect(-20,-34,40,66);c.fillStyle='#9f6a4b';c.beginPath();c.moveTo(-27,-34);c.lineTo(0,-56);c.lineTo(27,-34);c.closePath();c.fill()}else{c.fillStyle='#686d72';c.fillRect(-38,-20,76,40);for(let x=-32;x<=32;x+=16)c.fillRect(x,-30,10,12)}const hp=d.hp/d.maxHp;c.fillStyle='#3d1715';c.fillRect(-34,-45,68,6);c.fillStyle='#d34d47';c.fillRect(-34,-45,68*hp,6);c.restore()}const land=rivalPortLandPoint();if(land){const p=state.coastalSiege.port;c.save();c.translate(land.x,land.y);c.globalAlpha=worldVisibility(land.x,land.y)===2?1:.4;c.strokeStyle=p.owner==='player'?'#62d998':'#e55d55';c.lineWidth=5/state.camera.zoom;c.setLineDash([12/state.camera.zoom,7/state.camera.zoom]);c.beginPath();c.arc(0,0,105,0,Math.PI*2);c.stroke();c.setLineDash([]);c.fillStyle='rgba(5,12,21,.8)';c.fillRect(-70,-88,140,16);c.fillStyle=p.owner==='player'?'#62d998':'#e5c35e';c.fillRect(-68,-86,136*(p.progress/100),12);c.fillStyle='#fff0bd';c.font='bold 10px Georgia';c.textAlign='center';c.fillText(p.owner==='player'?'PORTO CONQUISTADO':p.fortificationHp>0?`FORTIFICAÇÃO ${Math.ceil(p.fortificationHp)}`:`CAPTURA ${Math.floor(p.progress)}%`,0,-96);c.restore()}}
function updateCoastalSiegeUI(){const c=state.coastalSiege||defaultCoastalSiege(),walls=state.buildings.filter(b=>b.complete&&b.type==='coastalWall').length,towers=state.buildings.filter(b=>b.complete&&b.type==='beachTower').length,rams=state.units.filter(u=>u.type==='siegeRam'&&u.hp>0).length;if($('coastalWallsStat'))$('coastalWallsStat').textContent=String(walls);if($('beachTowersStat'))$('beachTowersStat').textContent=String(towers);if($('siegeRamsStat'))$('siegeRamsStat').textContent=String(rams);if($('portCaptureStat'))$('portCaptureStat').textContent=c.port.owner==='player'?'CONQUISTADO':`${Math.floor(c.port.progress)}%`;if($('portFortificationStat'))$('portFortificationStat').textContent=String(Math.ceil(c.port.fortificationHp||0));}


function orientation(){const portrait=innerHeight>innerWidth;$('rotateHint').classList.toggle('hidden',!portrait)}

function applyCampaignCarryRewards(){state.campaignProgress=normalizeCampaignProgress(state.campaignProgress||loadCampaignProgress());for(const [k,v] of Object.entries(state.campaignProgress.cumulativeRewards||{}))state.stock[k]=(state.stock[k]||0)+Math.round(v*.25)}
function applyMissionSetup(key){const ai=state.enemyAI;if(key==='foundation'){if(ai)ai.attackTimer=-26000}else if(key==='frontier'){state.stock.food+=160;state.stock.wood+=100;spawnMilitary('infantry');spawnMilitary('infantry');spawnMilitary('archer');if(ai)ai.attackTimer=35000}else if(key==='ascension'){state.stock.wood+=250;state.stock.food+=260;state.stock.gold+=120;state.stock.stone+=80;if(ai)ai.attackTimer=-12000}else if(key==='siege'){state.stock.wood+=220;state.stock.food+=300;state.stock.gold+=180;for(let i=0;i<4;i++)spawnMilitary('infantry');for(let i=0;i<2;i++)spawnMilitary('archer');if(ai)ai.attackTimer=43000}else if(key==='crown'){state.stock.wood+=350;state.stock.food+=400;state.stock.gold+=250;state.stock.stone+=180;for(let i=0;i<4;i++)spawnMilitary('infantry');for(let i=0;i<3;i++)spawnMilitary('archer');for(let i=0;i<2;i++)spawnMilitary('cavalry');if(ai){ai.attackTimer=42000;ai.wave=Math.max(1,ai.wave||0)}}}
function openCampaignMap(){state.gameMode='campaign';state.pendingGameMode='campaign';state.campaignProgress=loadCampaignProgress();state.campaignSelected=state.campaignSelected&&state.campaignProgress.unlocked.includes(state.campaignSelected)?state.campaignSelected:state.campaignProgress.unlocked[state.campaignProgress.unlocked.length-1]||'foundation';hideCampaignResult();renderCampaignMap();show('campaign')}
function renderCampaignMap(){const p=normalizeProfile(state.profile||loadProfile(),true),a=AVATAR_DEFS[p.avatar],n=nationById(p.nation),progress=state.campaignProgress||loadCampaignProgress();if($('campaignAvatar'))$('campaignAvatar').src=a.src;if($('campaignFlag')){$('campaignFlag').src=n.flag;$('campaignFlag').alt=`Bandeira de ${n.label}`;}if($('campaignRuler'))$('campaignRuler').textContent=p.name;if($('campaignNation'))$('campaignNation').textContent=`${n.sigil} ${n.label}`;if($('campaignStars'))$('campaignStars').textContent=`${progress.completed.length} de ${CAMPAIGN_MISSIONS.length} capítulos concluídos`;document.querySelectorAll('.mission-node').forEach(node=>{const key=node.dataset.mission,unlocked=progress.unlocked.includes(key),completed=progress.completed.includes(key);node.classList.toggle('locked',!unlocked);node.classList.toggle('completed',completed);node.classList.toggle('selected',key===state.campaignSelected);const tag=node.querySelector('b');if(tag)tag.textContent=completed?'CONCLUÍDA':unlocked?'DISPONÍVEL':'BLOQUEADA'});renderCampaignBriefing()}
function selectCampaignMission(key){const progress=state.campaignProgress||loadCampaignProgress();if(!progress.unlocked.includes(key))return;state.campaignSelected=key;renderCampaignMap()}
function renderCampaignBriefing(){const m=missionByKey(state.campaignSelected),meta=MISSION_META[m.key]||MISSION_META.foundation,progress=state.campaignProgress||loadCampaignProgress(),best=progress.best?.[m.key];if($('campaignChapter'))$('campaignChapter').textContent=`CAPÍTULO ${m.chapter} • ${m.region.toUpperCase()}`;if($('campaignMissionTitle'))$('campaignMissionTitle').textContent=m.title;if($('campaignMissionDescription'))$('campaignMissionDescription').textContent=m.description;if($('campaignReward'))$('campaignReward').textContent=rewardText(difficultyReward(m.reward));if($('campaignDifficulty'))$('campaignDifficulty').textContent=meta.difficulty;if($('campaignDuration'))$('campaignDuration').textContent=meta.duration;if($('campaignBest'))$('campaignBest').textContent=best?`${DIFFICULTY_DEFS[normalizeDifficulty(best.difficulty||'normal')].label} • ${'★'.repeat(best.stars||1)} • ${formatMissionTime(best.elapsed||0)}`:'AINDA NÃO CONCLUÍDA';if($('campaignTip'))$('campaignTip').textContent=meta.tip;if($('campaignObjectivesPreview'))$('campaignObjectivesPreview').innerHTML=missionObjectiveLabels(m.key).map(o=>`<div class="campaign-preview-objective"><img src="${o.icon}" alt=""><span>${o.label}</span></div>`).join('');const start=$('btnCampaignStart');if(start){const completed=progress.completed.includes(m.key);start.textContent=completed?'JOGAR NOVAMENTE':'INICIAR MISSÃO'}const guide=$('btnCampaignTutorial');if(guide)guide.classList.toggle('hidden',m.key!=='foundation');updateDifficultyUI()}
function missionObjectiveLabels(key){const dummy={foundation:[['Coletar 180 recursos','assets/ui/icons-upgrade/resources/icon-wood.png'],['Concluir 2 casas','assets/ui/icons-upgrade/buildings/icon-house.png'],['Concluir 1 quartel','assets/ui/icons-upgrade/buildings/icon-barracks.png']],frontier:[['Eliminar 8 invasores','assets/ui/icons-upgrade/commands/icon-attack.png'],['Sobreviver à primeira onda','assets/ui/icons-upgrade/status/icon-attention.png'],['Manter 5 tropas ativas','assets/ui/icons-upgrade/military/icon-select-all-army.png']],ascension:[['Alcançar a Era Feudal','assets/ui/icons-upgrade/others/icon-technology.png'],['Concluir 2 tecnologias','assets/ui/icons-upgrade/others/icon-technology.png'],['Atingir limite populacional 20','assets/ui/icons-upgrade/resources/icon-population.png']],siege:[['Eliminar 18 inimigos','assets/ui/icons-upgrade/commands/icon-attack.png'],['Sobreviver a 2 ondas','assets/ui/icons-upgrade/status/icon-attention.png'],['Reunir 8 tropas','assets/ui/icons-upgrade/military/icon-select-all-army.png'],['Controlar 1 ponto estratégico','assets/ui/icons-upgrade/minimap/icon-marker.png']],crown:[['Alcançar a Era dos Reinos','assets/ui/icons-upgrade/others/icon-technology.png'],['Eliminar 30 inimigos','assets/ui/icons-upgrade/commands/icon-attack.png'],['Sobreviver a 4 ondas','assets/ui/icons-upgrade/status/icon-attention.png'],['Concluir tecnologia nacional','assets/ui/icons-upgrade/others/icon-technology.png'],['Controlar 3 pontos estratégicos','assets/ui/icons-upgrade/minimap/icon-marker.png']]};return(dummy[key]||[]).map(([label,icon])=>({label,icon}))}
function startSelectedMission(){state.gameMode='campaign';state.pendingGameMode='campaign';const progress=state.campaignProgress||loadCampaignProgress();if(!progress.unlocked.includes(state.campaignSelected)){return}state.campaign={currentMission:state.campaignSelected,startedAt:Date.now(),result:null,midpointShown:false,introShown:false,elapsed:0,lastHudUpdate:0,difficulty:normalizeDifficulty(state.difficulty)};start(false)}
function showCampaignDialogue(lines){if(!Array.isArray(lines)||!lines.length)return;state.dialogueQueue=lines;state.dialogueIndex=0;renderCampaignDialogue();$('campaignDialogueOverlay').classList.remove('hidden');$('campaignDialogueOverlay').setAttribute('aria-hidden','false')}
function renderCampaignDialogue(){const line=state.dialogueQueue[state.dialogueIndex];if(!line)return;if($('dialoguePortrait'))$('dialoguePortrait').src=line.portrait||'assets/ui/icons-upgrade/interface/icon-missions.png';if($('dialogueSpeaker'))$('dialogueSpeaker').textContent=line.speaker||'CRÔNICA';if($('dialogueText'))$('dialogueText').textContent=line.text||'';if($('dialogueCounter'))$('dialogueCounter').textContent=`${state.dialogueIndex+1} / ${state.dialogueQueue.length}`;if($('btnDialogueNext'))$('btnDialogueNext').textContent=state.dialogueIndex>=state.dialogueQueue.length-1?'COMEÇAR':'CONTINUAR'}
function nextCampaignDialogue(){state.dialogueIndex++;if(state.dialogueIndex>=state.dialogueQueue.length){$('campaignDialogueOverlay').classList.add('hidden');$('campaignDialogueOverlay').setAttribute('aria-hidden','true');state.dialogueQueue=[];state.dialogueIndex=0;return}renderCampaignDialogue()}
function showMissionIntro(){if(!state.campaign||state.campaign.introShown)return;state.campaign.introShown=true;showCampaignDialogue(missionByKey(state.campaign.currentMission).intro)}
function updateMissionHUD(force=false){if(!state.campaign)return;state.campaignHudTimer=force?999:state.campaignHudTimer;const m=missionByKey(state.campaign.currentMission),objs=missionObjectiveData(),done=objs.filter(objectiveDone).length,active=objs.find(o=>!objectiveDone(o))||objs[objs.length-1];if($('missionHudChapter'))$('missionHudChapter').textContent=`CAPÍTULO ${m.chapter}`;if($('missionHudTitle'))$('missionHudTitle').textContent=m.short;if($('missionHudProgress'))$('missionHudProgress').textContent=`${done} / ${objs.length} objetivos`;if($('missionTrackerTitle'))$('missionTrackerTitle').textContent=m.title;if($('missionTrackerText'))$('missionTrackerText').textContent=active?`${active.label}: ${Math.min(active.current,active.target)} / ${active.target}`:'Todos os objetivos concluídos';if($('btnMissionPanel'))$('btnMissionPanel').classList.toggle('complete',done===objs.length)}
function openMissionPanel(){if(!state.campaign)return;const m=missionByKey(state.campaign.currentMission),objs=missionObjectiveData();const html=`<div class="mission-panel-shell"><div class="mission-panel-intro"><img src="assets/ui/icons-upgrade/interface/icon-missions.png" alt="Missão"><div><strong>Capítulo ${m.chapter} — ${m.title}</strong><span>${m.description}</span></div></div><div class="mission-objective-list">${objs.map(o=>`<div class="mission-objective-row ${objectiveDone(o)?'done':''}"><img src="${o.icon}" alt=""><div><strong>${o.label}</strong><span>${objectiveDone(o)?'Objetivo concluído':'Objetivo em andamento'}</span></div><b>${Math.min(o.current,o.target)} / ${o.target}</b></div>`).join('')}</div><div class="campaign-result-reward">Recompensa: ${rewardText(m.reward)}</div><div class="campaign-tip"><img src="assets/ui/icons-upgrade/interface/icon-help.png" alt="Dica"><span>${(MISSION_META[m.key]||MISSION_META.foundation).tip}</span></div></div>`;openModal('Objetivos da missão',html)}
function updateCampaign(dt){if(state.tutorial?.active)return;if(!state.campaign||state.campaign.result)return;state.campaign.elapsed+=dt;state.campaignHudTimer+=dt;if(state.campaignHudTimer>=500){state.campaignHudTimer=0;updateMissionHUD()}if(state.campaign.elapsed>5000&&currentPopulation()===0){campaignDefeat('Seu exército e seus trabalhadores foram eliminados.');return}const objs=missionObjectiveData(),done=objs.filter(objectiveDone).length;if(!state.campaign.midpointShown&&done>=Math.ceil(objs.length/2)){state.campaign.midpointShown=true;showCampaignDialogue(missionByKey(state.campaign.currentMission).midpoint)}if(objs.length&&done===objs.length)campaignVictory()}
function formatMissionTime(ms){const total=Math.max(0,Math.round(Number(ms)||0)/1000),min=Math.floor(total/60),sec=Math.round(total%60);return `${min}:${String(sec).padStart(2,'0')}`}
function missionStars(m,elapsed=state.campaign?.elapsed||0,defeats=state.defeats){const meta=MISSION_META[m.key]||MISSION_META.foundation,d=DIFFICULTY_DEFS[normalizeDifficulty(state.campaign?.difficulty||state.difficulty)];let stars=1;if(defeats<=d.defeatAllowance)stars++;if(elapsed<=meta.parTime*d.parTime)stars++;return Math.max(1,Math.min(3,stars))}
function campaignVictory(){if(state.campaign?.result)return;window.VALE_AUDIO?.playResult?.(true);state.campaign.result='victory';const m=missionByKey(state.campaign.currentMission),progress=state.campaignProgress||loadCampaignProgress(),first=!progress.completed.includes(m.key),stars=missionStars(m);if(first){progress.completed.push(m.key);for(const [k,v] of Object.entries(difficultyReward(m.reward)))progress.cumulativeRewards[k]=(progress.cumulativeRewards[k]||0)+v;const index=CAMPAIGN_MISSIONS.findIndex(x=>x.key===m.key),next=CAMPAIGN_MISSIONS[index+1];if(next&&!progress.unlocked.includes(next.key))progress.unlocked.push(next.key)}const record={completedAt:new Date().toISOString(),kills:state.kills,defeats:state.defeats,elapsed:Math.round(state.campaign.elapsed),stars,difficulty:normalizeDifficulty(state.campaign?.difficulty||state.difficulty)};const previous=progress.best[m.key],betterDifficulty=!previous||difficultyRank(record.difficulty)>difficultyRank(previous.difficulty||'normal'),sameDifficulty=previous&&difficultyRank(record.difficulty)===difficultyRank(previous.difficulty||'normal');if(!previous||betterDifficulty||(sameDifficulty&&(stars>(previous.stars||1)||(stars===(previous.stars||1)&&record.elapsed<previous.elapsed))))progress.best[m.key]=record;state.campaignProgress=progress;persistCampaignProgress();for(const [k,v] of Object.entries(difficultyReward(m.reward)))state.stock[k]=Math.min((state.storage[k]||9999),(state.stock[k]||0)+v);updateStockUI();showCampaignResult(true,m);save()}
function campaignDefeat(reason){if(state.campaign?.result)return;window.VALE_AUDIO?.playResult?.(false);state.campaign.result='defeat';showCampaignResult(false,missionByKey(state.campaign.currentMission),reason)}
function showCampaignResult(victory,m,reason=''){const overlay=$('campaignResultOverlay');overlay.classList.remove('hidden');overlay.setAttribute('aria-hidden','false');$('campaignResultIcon').src=victory?'assets/ui/icons-upgrade/status/icon-available.png':'assets/ui/icons-upgrade/status/icon-blocked.png';$('campaignResultKicker').textContent=victory?'MISSÃO CONCLUÍDA':'MISSÃO FRACASSADA';$('campaignResultTitle').textContent=victory?m.title:'O reino foi derrotado';$('campaignResultText').textContent=victory?m.victory:reason;if(victory){const stars=missionStars(m),time=formatMissionTime(state.campaign?.elapsed||0);$('campaignResultReward').innerHTML=`<div class="mission-stars">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</div><div class="mission-performance"><div><small>TEMPO</small><b>${time}</b></div><div><small>ABATES</small><b>${state.kills}</b></div><div><small>BAIXAS</small><b>${state.defeats}</b></div></div><div style="margin-top:.65rem">Dificuldade: ${currentDifficulty().label}<br>Recompensa recebida: ${rewardText(difficultyReward(m.reward))}</div>`}else $('campaignResultReward').textContent='Reorganize suas forças, consulte as dicas e tente novamente.';$('btnCampaignResultPrimary').textContent=victory?'PRÓXIMO CAPÍTULO':'TENTAR NOVAMENTE'}
function hideCampaignResult(){if($('campaignResultOverlay')){$('campaignResultOverlay').classList.add('hidden');$('campaignResultOverlay').setAttribute('aria-hidden','true')}}
function campaignResultPrimary(){if(!state.campaign)return;const victory=state.campaign.result==='victory',current=state.campaign.currentMission;if(victory){const i=CAMPAIGN_MISSIONS.findIndex(m=>m.key===current),next=CAMPAIGN_MISSIONS[i+1];if(next&&(state.campaignProgress||loadCampaignProgress()).unlocked.includes(next.key))state.campaignSelected=next.key;openCampaignMap()}else{hideCampaignResult();state.campaignSelected=current;start(false)}}


function tutorialStored(){try{return JSON.parse(localStorage.getItem('valeEmpires.tutorial')||'null')}catch{return null}}
function persistTutorial(data){localStorage.setItem('valeEmpires.tutorial',JSON.stringify(data));return data}
function tutorialCondition(step){const t=state.tutorial;if(!t)return false;switch(step.id){case'camera':return Math.hypot(state.camera.x-t.baseline.camera.x,state.camera.y-t.baseline.camera.y)>55;case'select':return state.units.some(u=>state.selected.has(u.id)&&u.type==='villager');case'gather':return state.totalGathered>t.baseline.gathered;case'houses':return campaignBuildingCount('house')>=t.baseline.houses+2;case'mill':return campaignBuildingCount('mill')>=t.baseline.mills+1;case'villager':return state.units.filter(u=>u.type==='villager').length>t.baseline.villagers;case'barracks':return campaignBuildingCount('barracks')>=t.baseline.barracks+1;case'infantry':return state.units.some(u=>u.type==='infantry');case'technology':return state.technologies.length>t.baseline.techs;case'era':return state.eraIndex>t.baseline.era;case'combat':return state.kills>t.baseline.kills;case'territory':return (state.territoryStats.pointsPlayer||0)>t.baseline.points;case'save':return t.signals.has('save');default:return false}}
function clearTutorialHighlight(){document.querySelectorAll('.tutorial-highlight').forEach(el=>el.classList.remove('tutorial-highlight'))}
function applyTutorialHighlight(step){clearTutorialHighlight();for(const selector of step.highlight||[]){const candidates=[...document.querySelectorAll(selector)],el=candidates.find(x=>!x.classList.contains('hidden')&&getComputedStyle(x).display!=='none');if(el){el.classList.add('tutorial-highlight');break}}}
function renderTutorialStep(force=false){const t=state.tutorial,overlay=$('tutorialOverlay');if(!t||!t.active||!overlay)return;const step=TUTORIAL_STEPS[t.index];if(!step){completeTutorial();return}overlay.classList.remove('hidden','tutorial-complete');overlay.setAttribute('aria-hidden','false');$('tutorialIcon').src=step.icon;$('tutorialKicker').textContent=`TUTORIAL • ETAPA ${t.index+1} DE ${TUTORIAL_STEPS.length}`;$('tutorialTitle').textContent=step.title;$('tutorialText').textContent=step.text;$('tutorialHint').textContent=step.hint;$('tutorialProgressBar').style.width=`${Math.round(t.index/TUTORIAL_STEPS.length*100)}%`;$('btnTutorialNext').classList.toggle('hidden',!step.manual);$('btnTutorialNext').textContent=step.id==='welcome'?'COMEÇAR':'CONTINUAR';$('btnTutorialSkipStep').classList.toggle('hidden',!!step.manual);applyTutorialHighlight(step);if(force)window.VALE_AUDIO?.playSfx?.('notification',{category:'ui',volume:.45,minGap:240})}
function startTutorial(){state.tutorialRequested=false;hideCampaignResult();const villagers=state.units.filter(u=>u.type==='villager').length;state.tutorial={active:true,index:0,signals:new Set(),advanceAt:0,baseline:{camera:{x:state.camera.x,y:state.camera.y},gathered:state.totalGathered,houses:campaignBuildingCount('house'),mills:campaignBuildingCount('mill'),villagers,barracks:campaignBuildingCount('barracks'),techs:state.technologies.length,era:state.eraIndex,kills:state.kills,points:state.territoryStats.pointsPlayer||0}};state.stock={wood:Math.max(state.stock.wood,1400),food:Math.max(state.stock.food,1400),gold:Math.max(state.stock.gold,900),stone:Math.max(state.stock.stone,900)};state.storage={wood:2000,food:2000,gold:1600,stone:1600};state.population.cap=Math.max(state.population.cap,24);recalculateEconomy();updateStockUI();if($('campaignDialogueOverlay'))$('campaignDialogueOverlay').classList.add('hidden');updateMissionHUD(true);renderTutorialStep(true);status('Tutorial guiado iniciado')}
function tutorialPrimaryAction(){const t=state.tutorial;if(!t?.active)return;const step=TUTORIAL_STEPS[t.index];if(step?.manual){t.index++;renderTutorialStep(true)}}
function skipTutorialStep(){const t=state.tutorial;if(!t?.active)return;t.index++;t.advanceAt=0;renderTutorialStep(true)}
function tutorialSignal(name){if(state.tutorial?.active)state.tutorial.signals.add(name)}
function updateTutorial(dt){const t=state.tutorial;if(!t?.active)return;const step=TUTORIAL_STEPS[t.index];if(!step){completeTutorial();return}if(step.manual)return;if(tutorialCondition(step)){if(!t.advanceAt){t.advanceAt=performance.now()+650;status(`Tutorial concluído: ${step.title}`);window.VALE_AUDIO?.playSfx?.('ui-confirm',{category:'ui',volume:.62,minGap:200})}if(performance.now()>=t.advanceAt){t.index++;t.advanceAt=0;renderTutorialStep(true)}}}
function completeTutorial(){const t=state.tutorial;if(!t)return;t.active=false;clearTutorialHighlight();persistTutorial({completed:true,completedAt:new Date().toISOString(),buildId:BUILD.buildId});const overlay=$('tutorialOverlay');overlay.classList.remove('hidden');overlay.classList.add('tutorial-complete');$('tutorialIcon').src='assets/ui/icons-upgrade/status/icon-available.png';$('tutorialKicker').textContent='TREINAMENTO CONCLUÍDO';$('tutorialTitle').textContent='Você está pronto para governar';$('tutorialText').textContent='Você aprendeu câmera, economia, construção, população, exército, tecnologia, eras, combate, território e salvamento.';$('tutorialHint').textContent='Volte ao mapa da campanha para iniciar o Capítulo I com progresso limpo.';$('tutorialProgressBar').style.width='100%';$('btnTutorialNext').classList.remove('hidden');$('btnTutorialNext').textContent='IR PARA A CAMPANHA';$('btnTutorialNext').onclick=()=>{hideTutorialOverlay();openCampaignMap()};$('btnTutorialSkipStep').classList.add('hidden');$('btnTutorialExit').textContent='MENU PRINCIPAL';$('btnTutorialExit').onclick=()=>{hideTutorialOverlay();show('menu')}}
function hideTutorialOverlay(){clearTutorialHighlight();const overlay=$('tutorialOverlay');if(overlay){overlay.classList.add('hidden');overlay.classList.remove('tutorial-complete');overlay.setAttribute('aria-hidden','true')}const returnDifficulty=localStorage.getItem('valeEmpires.tutorialReturnDifficulty');if(returnDifficulty){persistDifficulty(returnDifficulty);localStorage.removeItem('valeEmpires.tutorialReturnDifficulty')}state.tutorial=null;state.tutorialRequested=false;if($('btnTutorialNext'))$('btnTutorialNext').onclick=tutorialPrimaryAction;if($('btnTutorialExit')){$('btnTutorialExit').onclick=exitTutorial;$('btnTutorialExit').textContent='SAIR'}}
function exitTutorial(){if(!state.tutorial?.active){hideTutorialOverlay();return}persistTutorial({completed:false,lastStep:state.tutorial.index,updatedAt:new Date().toISOString(),buildId:BUILD.buildId});hideTutorialOverlay();openCampaignMap()}
async function openTutorialEntry(){await enterFullscreen();state.gameMode='campaign';state.pendingGameMode='campaign';state.periodPack='medieval';persistEraPack('medieval');localStorage.setItem('valeEmpires.tutorialReturnDifficulty',normalizeDifficulty(state.difficulty));state.difficulty='story';updateDifficultyUI();state.tutorialRequested=true;const p=normalizeProfile(loadProfile(),false);if(p){state.profile={...p,eraPack:'medieval'};persistProfile(state.profile);state.campaignSelected='foundation';start(false)}else openProfileSetup(false)}
function openTutorialHelp(){if(state.tutorial?.active){renderTutorialStep(true);return}const done=!!tutorialStored()?.completed;openModal('Tutorial e ajuda',`<div class="credit-card"><p><strong>${done?'Tutorial concluído':'Tutorial ainda não concluído'}</strong></p><p>O treinamento guiado cobre câmera, coleta, construção, produção, tecnologia, evolução de era, combate, território e salvamento.</p><div class="settings-action-row"><button class="hud-button" id="restartTutorialBtn">${done?'REPETIR TUTORIAL':'INICIAR TUTORIAL'}</button></div></div>`);setTimeout(()=>{const b=$('restartTutorialBtn');if(b)b.onclick=()=>{closeModal();openTutorialEntry()}},0)}



