function defaultUrbanSiege(){return{version:1,city:{owner:'enemy',progress:0,keepHp:1800,maxKeepHp:1800,contested:false,capturedAt:0,incomeTimer:0,x:0,y:0,rewardGranted:false},enemyStructures:[],stats:{wallsBuilt:0,gatesBuilt:0,towersBuilt:0,siegeTowersTrained:0,citiesCaptured:0,citiesLost:0,structuresDestroyed:0,gatesBreached:0},towerTimer:0,captureTimer:0,counterTimer:0}}
function normalizeUrbanSiege(saved){const base=defaultUrbanSiege(),src=saved&&typeof saved==='object'?saved:{};base.city={...base.city,...(src.city||{})};base.city.progress=Math.max(0,Math.min(100,Number(base.city.progress)||0));base.city.keepHp=Math.max(0,Number(base.city.keepHp)||base.city.maxKeepHp);base.stats={...base.stats,...(src.stats||{})};base.enemyStructures=Array.isArray(src.enemyStructures)?src.enemyStructures.map((d,i)=>({...d,id:Number(d.id)||i+1,hp:Math.max(0,Number(d.hp)||Number(d.maxHp)||700),maxHp:Math.max(1,Number(d.maxHp)||700),cooldown:Number(d.cooldown)||0,open:!!d.open})):[];return base}
function serializeUrbanSiege(){if(!state.urbanSiege)return null;return{version:1,city:{...state.urbanSiege.city},enemyStructures:state.urbanSiege.enemyStructures.map(d=>({...d})),stats:{...state.urbanSiege.stats},towerTimer:state.urbanSiege.towerTimer||0,captureTimer:state.urbanSiege.captureTimer||0,counterTimer:state.urbanSiege.counterTimer||0}}
function enemyCityCenter(){const port=rivalPortLandPoint();if(!port||!state.map)return null;return nearestPassable(port.x,Math.max(state.map.tile*3,port.y-state.map.tile*3.3))||nearestPassable(port.x,port.y-state.map.tile*2.4)||port}
function initializeUrbanSiege(saved=null){state.urbanSiege=normalizeUrbanSiege(saved);if(!state.urbanSiege.enemyStructures.length){const center=enemyCityCenter();if(center){state.urbanSiege.city.x=center.x;state.urbanSiege.city.y=center.y;const layout=[
 ['wall',-210,-150],['wall',-105,-150],['gate',0,-150],['wall',105,-150],['wall',210,-150],
 ['wall',-240,-40],['tower',-240,-145],['wall',-240,70],['tower',-240,160],
 ['wall',240,-40],['tower',240,-145],['wall',240,70],['tower',240,160],
 ['wall',-210,170],['wall',-105,170],['gate',0,170],['wall',105,170],['wall',210,170],['keep',0,10]
];state.urbanSiege.enemyStructures=layout.map((d,i)=>{const p=nearestPassable(center.x+d[1],center.y+d[2])||center;const hp=d[0]==='keep'?1800:d[0]==='tower'?850:d[0]==='gate'?1050:920;return{id:i+1,type:d[0],x:p.x,y:p.y,hp,maxHp:hp,cooldown:0,open:false}})}}updateUrbanSiegeUI()}
function locateEnemyCity(){const p=enemyCityCenter();if(!p){status('Cidade costeira rival indisponível.');return}state.camera.x=p.x-innerWidth/(2*state.camera.zoom);state.camera.y=p.y-innerHeight/(2*state.camera.zoom);clamp();status('Câmera posicionada na cidade costeira rival.')}
function togglePlayerCityGates(){const gates=state.buildings.filter(b=>b.complete&&b.type==='cityGate');if(!gates.length){status('Construa ao menos um Portão Fortificado.');return}const open=!gates.every(g=>g.gateOpen);for(const g of gates)g.gateOpen=open;status(`${gates.length} portão(ões) ${open?'aberto(s)':'fechado(s)'}.`);window.VALE_AUDIO?.playSfx?.('ui-confirm',{category:'ui',volume:.62,minGap:180});updateUrbanSiegeUI()}
function drawPlayerUrbanFortification(b){const c=state.ctx,d=BUILDING_DEFS[b.type],s=d.size,hp=Math.max(0,Math.min(1,b.hp/b.maxHp));c.save();c.translate(b.x,b.y);c.fillStyle='rgba(0,0,0,.34)';c.beginPath();c.ellipse(0,s*.34,s*.72,s*.20,0,0,Math.PI*2);c.fill();if(b.type==='cityWall'){c.fillStyle=b.complete?'#777d82':'rgba(119,125,130,.48)';c.fillRect(-s*.72,-s*.26,s*1.44,s*.62);c.fillStyle='#989da1';for(let x=-s*.62;x<=s*.62;x+=s*.30)c.fillRect(x,-s*.40,s*.16,s*.18)}else if(b.type==='cityGate'){c.fillStyle=b.complete?'#6f747a':'rgba(111,116,122,.48)';c.fillRect(-s*.62,-s*.40,s*1.24,s*.80);c.fillStyle='#4d3423';if(b.gateOpen){c.fillRect(-s*.52,-s*.24,s*.16,s*.57);c.fillRect(s*.36,-s*.24,s*.16,s*.57)}else c.fillRect(-s*.34,-s*.24,s*.68,s*.57);c.fillStyle='#d5b46b';c.font='bold 9px Georgia';c.textAlign='center';c.fillText(b.gateOpen?'ABERTO':'FECHADO',0,s*.58)}else{c.fillStyle=b.complete?'#65717d':'rgba(101,113,125,.48)';c.fillRect(-s*.36,-s*.48,s*.72,s*.92);c.fillStyle='#8a9299';c.beginPath();c.moveTo(-s*.48,-s*.48);c.lineTo(0,-s*.78);c.lineTo(s*.48,-s*.48);c.closePath();c.fill();c.fillStyle='#caa65d';c.fillRect(-4,-s*.68,8,s*.40)}c.fillStyle='#421b18';c.fillRect(-s*.46,-s*.70,s*.92,7);c.fillStyle=hp>.5?'#55ad65':'#d25b4d';c.fillRect(-s*.46,-s*.70,s*.92*hp,7);c.restore()}
function urbanFriendlyTroops(point,radius=235){return state.units.filter(u=>u.hp>0&&u.type!=='villager'&&Math.hypot(u.x-point.x,u.y-point.y)<=radius)}
function urbanEnemyTroops(point,radius=235){return state.enemies.filter(e=>e.hp>0&&!e.urbanRebel&&Math.hypot(e.x-point.x,e.y-point.y)<=radius)}
function nearestUrbanStructure(entity){let best=null,dist=Infinity;for(const d of state.urbanSiege?.enemyStructures||[]){if(d.hp<=0)continue;const dd=Math.hypot(entity.x-d.x,entity.y-d.y);if(dd<dist){best=d;dist=dd}}return best?{structure:best,dist}:null}
function damageUrbanStructure(attacker,target){const mult=attacker.type==='siegeTower'?2.9:attacker.type==='siegeRam'?2.35:1,raw=Math.max(4,Math.round((attacker.attack||10)*mult));target.hp=Math.max(0,target.hp-raw);attacker.cooldown=attacker.type==='siegeTower'?1600:1350;state.effects.push({x:target.x,y:target.y,life:650,maxLife:650,type:'damage',text:`-${raw}`,color:'#ffe09b'});window.VALE_AUDIO?.playSfx?.('impact',{volume:.72,minGap:130});if(target.hp<=0){state.urbanSiege.stats.structuresDestroyed++;if(target.type==='gate')state.urbanSiege.stats.gatesBreached++;if(target.type==='keep')state.urbanSiege.city.keepHp=0;state.effects.push({x:target.x,y:target.y,life:1000,maxLife:1000,type:'death',color:'#d8b36b'});diplomacyNotify(`${target.type==='keep'?'Cidadela':target.type==='gate'?'Portão':'Fortificação'} rival destruída.`)}}
function updateSiegeTowers(dt){if(!state.urbanSiege||state.coastalSiege?.port?.owner!=='player')return;for(const u of state.units.filter(x=>['siegeTower','siegeRam'].includes(x.type)&&x.hp>0)){u.cooldown=Math.max(0,(u.cooldown||0)-dt);const target=nearestUrbanStructure(u);if(!target)continue;const range=u.type==='siegeTower'?62:55;if(target.dist>range){setDestination(u,nearestPassable(target.structure.x,target.structure.y),false);u.state='engaging'}else if(u.cooldown<=0){u.target=null;clearRoute(u);u.state='fighting';damageUrbanStructure(u,target.structure)}}
for(const e of state.enemies.filter(x=>x.type==='siegeTower'&&x.hp>0)){e.cooldown=Math.max(0,(e.cooldown||0)-dt);let target=null,dist=Infinity;for(const b of state.buildings.filter(b=>b.complete&&['cityWall','cityGate','cityTower','townCenter','coastalFort'].includes(b.type))){const d=Math.hypot(e.x-b.x,e.y-b.y);if(d<dist){dist=d;target=b}}if(!target)continue;if(dist>68){setDestination(e,nearestPassable(target.x,target.y),false);e.state='engaged'}else if(e.cooldown<=0){const raw=Math.max(18,Math.round((e.attack||44)*2.2));target.hp=Math.max(0,target.hp-raw);e.cooldown=1650;state.effects.push({x:target.x,y:target.y,life:650,maxLife:650,type:'damage',text:`-${raw}`,color:'#ff8b79'});if(target.hp<=0)diplomacyNotify(`${BUILDING_DEFS[target.type]?.label||'Fortificação'} destruída pela torre de cerco inimiga!`,'warning')}}state.buildings=state.buildings.filter(b=>b.hp>0)}
function updateUrbanTowers(dt){for(const tower of state.buildings.filter(b=>b.complete&&b.type==='cityTower')){tower.defenseCooldown=Math.max(0,(tower.defenseCooldown||0)-dt);let target=null,dist=350;for(const e of state.enemies){const d=Math.hypot(e.x-tower.x,e.y-tower.y);if(e.hp>0&&d<dist){dist=d;target=e}}if(target&&tower.defenseCooldown<=0){const damage=20+state.eraIndex*5;target.hp-=damage;tower.defenseCooldown=1050;state.effects.push({x:target.x,y:target.y-10,life:520,maxLife:520,type:'damage',text:`-${damage}`,color:'#ffe09b'});window.VALE_AUDIO?.playSfx?.('arrow-shot',{volume:.5,minGap:110})}}
for(const tower of state.urbanSiege.enemyStructures.filter(d=>d.type==='tower'&&d.hp>0)){tower.cooldown=Math.max(0,(tower.cooldown||0)-dt);let target=null,dist=330;for(const u of state.units){const d=Math.hypot(u.x-tower.x,u.y-tower.y);if(u.hp>0&&d<dist){dist=d;target=u}}if(target&&tower.cooldown<=0){const damage=18+state.eraIndex*3;target.hp-=damage;tower.cooldown=1120;state.effects.push({x:target.x,y:target.y-8,life:520,maxLife:520,type:'damage',text:`-${damage}`,color:'#ff8b79'})}}}
function updateCityCapture(dt){const u=state.urbanSiege,center=enemyCityCenter();if(!u||!center)return;const friendly=urbanFriendlyTroops(center),enemy=urbanEnemyTroops(center),defensesAlive=u.enemyStructures.some(d=>d.hp>0&&d.type!=='keep'),keep=u.enemyStructures.find(d=>d.type==='keep');u.city.keepHp=keep?keep.hp:0;u.city.contested=!!(friendly.length&&enemy.length);const portOwned=state.coastalSiege?.port?.owner==='player';if(u.city.owner==='enemy'){if(portOwned&&friendly.length&&!enemy.length&&!defensesAlive&&u.city.keepHp<=0){u.city.progress=Math.min(100,u.city.progress+dt*(.0028+Math.min(8,friendly.length)*.00038));if(u.city.progress>=100){u.city.owner='player';u.city.capturedAt=Date.now();u.stats.citiesCaptured++;if(!u.city.rewardGranted){u.city.rewardGranted=true;state.stock.gold=Math.min(state.storage.gold||9999,(state.stock.gold||0)+350);state.stock.stone=Math.min(state.storage.stone||9999,(state.stock.stone||0)+250);state.population.cap+=8;}activateCityAdministration();diplomacyNotify('Cidade costeira conquistada! A administração urbana foi desbloqueada.');window.VALE_AUDIO?.playSfx?.('territory-capture',{volume:1,minGap:400});updateStockUI()}}else if(!friendly.length)u.city.progress=Math.max(0,u.city.progress-dt*.0008)}else{if(enemy.length&&!friendly.length){u.city.progress=Math.max(0,u.city.progress-dt*.0025);if(u.city.progress<=0){u.city.owner='enemy';u.city.keepHp=Math.round(u.city.maxKeepHp*.5);u.stats.citiesLost++;if(keep)keep.hp=u.city.keepHp;deactivateCityAdministration('retaken');diplomacyNotify('A cidade costeira foi retomada pelo rival!','warning')}}else u.city.progress=Math.min(100,u.city.progress+dt*.00035);u.city.incomeTimer+=dt;if(u.city.incomeTimer>=15000){u.city.incomeTimer=0;state.stock.gold=Math.min(state.storage.gold||9999,(state.stock.gold||0)+10);state.stock.stone=Math.min(state.storage.stone||9999,(state.stock.stone||0)+8);updateStockUI()}}}
function updateUrbanSiege(dt){if(!state.urbanSiege||!state.map)return;updateSiegeTowers(dt);updateUrbanTowers(dt);updateCityCapture(dt);state.urbanSiegeTimer+=dt;if(state.urbanSiegeTimer>=650){state.urbanSiegeTimer=0;updateUrbanSiegeUI()}}
function drawUrbanSiegeLayer(){if(!state.urbanSiege)return;const c=state.ctx;for(const d of state.urbanSiege.enemyStructures){if(d.hp<=0||worldVisibility(d.x,d.y)===0)continue;c.save();c.translate(d.x,d.y);c.globalAlpha=worldVisibility(d.x,d.y)===2?1:.44;if(d.type==='wall'){c.fillStyle='#6c7076';c.fillRect(-44,-22,88,44);c.fillStyle='#8e949a';for(let x=-36;x<=36;x+=18)c.fillRect(x,-33,12,14)}else if(d.type==='gate'){c.fillStyle='#686d73';c.fillRect(-52,-35,104,70);c.fillStyle='#4d3020';c.fillRect(-25,-17,50,52);c.fillStyle='#c3a362';c.font='bold 9px Georgia';c.textAlign='center';c.fillText('PORTÃO',0,49)}else if(d.type==='tower'){c.fillStyle='#6f3b37';c.fillRect(-23,-40,46,78);c.fillStyle='#9a694e';c.beginPath();c.moveTo(-31,-40);c.lineTo(0,-64);c.lineTo(31,-40);c.closePath();c.fill()}else{c.fillStyle='#77503d';c.fillRect(-64,-42,128,88);c.fillStyle='#995f43';c.beginPath();c.moveTo(-72,-42);c.lineTo(0,-92);c.lineTo(72,-42);c.closePath();c.fill();c.fillStyle='#e6c674';c.font='bold 11px Georgia';c.textAlign='center';c.fillText('CIDADELA',0,65)}const hp=d.hp/d.maxHp;c.fillStyle='#3d1715';c.fillRect(-40,-58,80,7);c.fillStyle='#d34d47';c.fillRect(-40,-58,80*hp,7);c.restore()}const center=enemyCityCenter();if(center){const city=state.urbanSiege.city;c.save();c.translate(center.x,center.y);c.globalAlpha=worldVisibility(center.x,center.y)===2?1:.42;c.strokeStyle=city.owner==='player'?'#62d998':'#e65b54';c.lineWidth=6/state.camera.zoom;c.setLineDash([14/state.camera.zoom,8/state.camera.zoom]);c.beginPath();c.arc(0,0,260,0,Math.PI*2);c.stroke();c.setLineDash([]);c.fillStyle='rgba(5,12,21,.84)';c.fillRect(-90,-130,180,18);c.fillStyle=city.owner==='player'?'#62d998':'#e5c35e';c.fillRect(-87,-127,174*(city.progress/100),12);c.fillStyle='#fff0bd';c.font='bold 11px Georgia';c.textAlign='center';c.fillText(city.owner==='player'?'CIDADE CONQUISTADA':city.keepHp>0?`CIDADELA ${Math.ceil(city.keepHp)}`:`OCUPAÇÃO ${Math.floor(city.progress)}%`,0,-140);c.restore()}}
function updateUrbanSiegeUI(){const u=state.urbanSiege||defaultUrbanSiege(),walls=state.buildings.filter(b=>b.complete&&b.type==='cityWall').length,gates=state.buildings.filter(b=>b.complete&&b.type==='cityGate').length,towers=state.buildings.filter(b=>b.complete&&b.type==='cityTower').length,siegeTowers=state.units.filter(x=>x.type==='siegeTower'&&x.hp>0).length;if($('cityWallsStat'))$('cityWallsStat').textContent=String(walls);if($('cityGatesStat'))$('cityGatesStat').textContent=String(gates);if($('cityTowersStat'))$('cityTowersStat').textContent=String(towers);if($('siegeTowersStat'))$('siegeTowersStat').textContent=String(siegeTowers);if($('cityCaptureStat'))$('cityCaptureStat').textContent=u.city.owner==='player'?'CONQUISTADA':`${Math.floor(u.city.progress)}%`;if($('cityKeepStat'))$('cityKeepStat').textContent=String(Math.ceil(u.city.keepHp||0));}


// ===== FASE 33 — ADMINISTRAÇÃO URBANA, GUARNIÇÕES, RECONSTRUÇÃO E REVOLTAS =====
const CITY_POLICIES={
 balanced:{key:'balanced',label:'Governo Equilibrado',description:'Equilibra renda, estabilidade e lealdade.',income:{gold:8,food:5},stability:.05,loyalty:.04,prosperity:.05,risk:-5},
 relief:{key:'relief',label:'Reconstrução Popular',description:'Prioriza alimento, obras e confiança da população.',income:{gold:3,food:3},stability:.09,loyalty:.12,prosperity:.07,risk:-12},
 tribute:{key:'tribute',label:'Tributo Intensivo',description:'Aumenta a arrecadação, mas eleva tensão e revolta.',income:{gold:16,stone:5},stability:-.04,loyalty:-.12,prosperity:.02,risk:18},
 martial:{key:'martial',label:'Lei Marcial',description:'Aumenta segurança e controle, reduzindo a confiança civil.',income:{gold:7,stone:4},stability:.11,loyalty:-.05,prosperity:-.02,risk:-8}
};
function defaultCityAdministration(){return{version:1,active:false,policy:'balanced',stability:0,loyalty:0,prosperity:0,reconstruction:0,integration:0,unrest:0,revoltRisk:0,garrisonIds:[],garrisonTarget:6,incomeTimer:0,updateTimer:0,revoltTimer:0,rebellionActive:false,rebellionWave:0,lastEvent:'Cidade ainda não conquistada',capturedAt:0,stats:{incomeCycles:0,totalGold:0,totalFood:0,totalWood:0,totalStone:0,revolts:0,revoltsSuppressed:0,reconstructionProjects:0,policiesChanged:0}}}
function normalizeCityAdministration(saved){const base=defaultCityAdministration(),src=saved&&typeof saved==='object'?saved:{};Object.assign(base,src);base.stats={...defaultCityAdministration().stats,...(src.stats||{})};base.policy=CITY_POLICIES[src.policy]?src.policy:'balanced';for(const k of ['stability','loyalty','prosperity','reconstruction','integration','unrest','revoltRisk'])base[k]=Math.max(0,Math.min(100,Number(base[k])||0));base.garrisonIds=Array.isArray(src.garrisonIds)?src.garrisonIds.map(Number).filter(Number.isFinite):[];base.garrisonTarget=Math.max(2,Math.min(12,Number(src.garrisonTarget)||6));base.active=!!src.active;base.rebellionActive=!!src.rebellionActive;return base}
function serializeCityAdministration(){if(!state.cityAdministration)return null;const a=state.cityAdministration;return{version:1,active:a.active,policy:a.policy,stability:a.stability,loyalty:a.loyalty,prosperity:a.prosperity,reconstruction:a.reconstruction,integration:a.integration,unrest:a.unrest,revoltRisk:a.revoltRisk,garrisonIds:[...a.garrisonIds],garrisonTarget:a.garrisonTarget,incomeTimer:a.incomeTimer,updateTimer:a.updateTimer,revoltTimer:a.revoltTimer,rebellionActive:a.rebellionActive,rebellionWave:a.rebellionWave,lastEvent:a.lastEvent,capturedAt:a.capturedAt,stats:{...a.stats}}}
function initializeCityAdministration(saved=null){state.cityAdministration=normalizeCityAdministration(saved);const cityOwned=state.urbanSiege?.city?.owner==='player';if(cityOwned&&!state.cityAdministration.active)activateCityAdministration(true);if(!cityOwned)state.cityAdministration.active=false;sanitizeCityGarrison();updateCityAdministrationUI()}
function activateCityAdministration(silent=false){const a=state.cityAdministration||defaultCityAdministration();state.cityAdministration=a;a.active=true;a.capturedAt=a.capturedAt||Date.now();a.stability=Math.max(a.stability,42);a.loyalty=Math.max(a.loyalty,36);a.prosperity=Math.max(a.prosperity,24);a.reconstruction=Math.max(a.reconstruction,18);a.lastEvent='Conselho urbano instalado após a conquista';if(!silent){status('Administração urbana desbloqueada');window.VALE_AUDIO?.playSfx?.('ui-confirm',{category:'ui',volume:.8,minGap:250})}updateCityAdministrationUI()}
function deactivateCityAdministration(reason='lost'){const a=state.cityAdministration||defaultCityAdministration();a.active=false;a.garrisonIds=[];a.rebellionActive=false;a.lastEvent=reason==='retaken'?'Administração interrompida: cidade retomada':'Administração suspensa';for(const u of state.units){if(u.garrisonCity){u.garrisonCity=false;if(u.task?.kind==='cityGarrison')u.task=null}}updateCityAdministrationUI()}
function sanitizeCityGarrison(){const a=state.cityAdministration;if(!a)return;a.garrisonIds=[...new Set(a.garrisonIds)].filter(id=>state.units.some(u=>u.id===id&&u.hp>0&&u.type!=='villager'));for(const u of state.units)u.garrisonCity=a.garrisonIds.includes(u.id)}
function cityGarrisonUnits(){sanitizeCityGarrison();const center=enemyCityCenter();if(!center)return[];return state.units.filter(u=>u.garrisonCity&&u.hp>0&&u.type!=='villager'&&Math.hypot(u.x-center.x,u.y-center.y)<390)}
function cityAdminPolicy(){return CITY_POLICIES[state.cityAdministration?.policy]||CITY_POLICIES.balanced}
function assignCityGarrisonFromSelection(){const a=state.cityAdministration;if(!a?.active){status('Conquiste a cidade antes de formar uma guarnição');return}const selected=state.units.filter(u=>state.selected.has(u.id)&&u.hp>0&&u.type!=='villager');if(!selected.length){status('Selecione tropas militares para a guarnição');return}const center=enemyCityCenter();if(!center)return;for(const [i,u] of selected.entries()){u.garrisonCity=true;if(!a.garrisonIds.includes(u.id))a.garrisonIds.push(u.id);u.task={kind:'cityGarrison'};u.state='moving';const angle=i/Math.max(1,selected.length)*Math.PI*2,p=nearestPassable(center.x+Math.cos(angle)*150,center.y+Math.sin(angle)*150)||center;setDestination(u,p,true)}a.lastEvent=`${selected.length} tropa(s) enviada(s) à guarnição`;status(a.lastEvent);updateCityAdministrationUI();openCityAdministrationPanel()}
function releaseCityGarrison(){const a=state.cityAdministration;if(!a)return;for(const u of state.units){if(u.garrisonCity){u.garrisonCity=false;if(u.task?.kind==='cityGarrison')u.task=null}}a.garrisonIds=[];a.lastEvent='Guarnição liberada para operações de campo';status(a.lastEvent);updateCityAdministrationUI();openCityAdministrationPanel()}
function setCityPolicy(policy){const a=state.cityAdministration,p=CITY_POLICIES[policy];if(!a?.active||!p)return;if(policy==='relief'&&!canAfford({food:90,wood:70})){status('Reconstrução Popular exige 90 alimento e 70 madeira');return}if(policy==='martial'&&!canAfford({gold:60})){status('Lei Marcial exige 60 ouro para mobilização');return}if(policy==='relief')spend({food:90,wood:70});if(policy==='martial')spend({gold:60});a.policy=policy;a.stats.policiesChanged++;a.lastEvent=`Política adotada: ${p.label}`;status(a.lastEvent);updateCityAdministrationUI();openCityAdministrationPanel()}
function fundCityReconstruction(){const a=state.cityAdministration;if(!a?.active)return;if(a.reconstruction>=100){status('A cidade já foi completamente reconstruída');return}const cost={wood:160,stone:120,gold:50};if(!canAfford(cost)){status('Reconstrução exige 160 madeira, 120 pedra e 50 ouro');return}spend(cost);a.reconstruction=Math.min(100,a.reconstruction+22);a.stability=Math.min(100,a.stability+9);a.loyalty=Math.min(100,a.loyalty+5);a.prosperity=Math.min(100,a.prosperity+7);a.stats.reconstructionProjects++;a.lastEvent='Projeto de reconstrução financiado';window.VALE_AUDIO?.playSfx?.('building-complete',{volume:.82,minGap:250});status(a.lastEvent);updateCityAdministrationUI();openCityAdministrationPanel()}
function grantCityRelief(){const a=state.cityAdministration;if(!a?.active)return;const cost={food:120,gold:45};if(!canAfford(cost)){status('Auxílio civil exige 120 alimento e 45 ouro');return}spend(cost);a.loyalty=Math.min(100,a.loyalty+14);a.stability=Math.min(100,a.stability+6);a.unrest=Math.max(0,a.unrest-18);a.lastEvent='Alimento e auxílio distribuídos à população';status(a.lastEvent);updateCityAdministrationUI();openCityAdministrationPanel()}
function cityIncomeTick(){const a=state.cityAdministration,p=cityAdminPolicy();if(!a.active||a.rebellionActive)return;const multiplier=.45+(a.prosperity/100)*.75+(a.integration/100)*.25;for(const [resource,base] of Object.entries(p.income)){const amount=Math.max(1,Math.round(base*multiplier));state.stock[resource]=Math.min(state.storage[resource]||9999,(state.stock[resource]||0)+amount);const stat='total'+resource[0].toUpperCase()+resource.slice(1);if(stat in a.stats)a.stats[stat]+=amount}a.stats.incomeCycles++;a.lastEvent=`Renda urbana recebida (${p.label})`;updateStockUI()}
function spawnCityRevolt(){const a=state.cityAdministration,center=enemyCityCenter();if(!a.active||a.rebellionActive||!center)return;a.rebellionActive=true;a.rebellionWave++;a.stats.revolts++;a.lastEvent=`Revolta urbana iniciada — onda ${a.rebellionWave}`;const count=Math.min(10,4+a.rebellionWave+Math.floor(a.revoltRisk/25));for(let i=0;i<count;i++){const angle=i/count*Math.PI*2,radius=95+(i%3)*34,p=nearestPassable(center.x+Math.cos(angle)*radius,center.y+Math.sin(angle)*radius)||center;const type=i%4===0?'archer':'infantry',e=normalizeEnemy({id:state.enemySeq++,type,name:`Rebelde urbano ${i+1}`,x:p.x,y:p.y,armor:type==='infantry'?2:0});e.faction='rebels';e.urbanRebel=true;e.home={x:center.x,y:center.y};e.aiOrder='assault';e.target={x:center.x,y:center.y};state.enemies.push(e)}diplomacyNotify('Revolta urbana! A guarnição precisa restaurar a ordem.','warning');window.VALE_AUDIO?.playSfx?.('notification',{category:'ui',volume:1,minGap:300});updateCityAdministrationUI()}
function updateCityRevoltResolution(){const a=state.cityAdministration;if(!a?.rebellionActive)return;const rebels=state.enemies.filter(e=>e.urbanRebel&&e.hp>0);if(!rebels.length){a.rebellionActive=false;a.stats.revoltsSuppressed++;a.stability=Math.min(100,a.stability+8);a.loyalty=Math.min(100,a.loyalty+4);a.unrest=Math.max(0,a.unrest-25);a.lastEvent='Revolta controlada pela guarnição';diplomacyNotify('Revolta urbana controlada. A ordem foi restaurada.');updateCityAdministrationUI()}}
